const TRAINING_KEY='weight-app-active-training-v1';
let finishingTraining=false,trainingEndedAt=null,exerciseLibraryScroll=0;let activeTraining=null,exerciseSort='frequent',exerciseCategory='Alle',exerciseSearch='',exerciseFocus=null,trainingReturn='session',restEnd=0,restLength=90,restPaused=90,restRunning=false,trainingTicker=null,photoFocus=null;
function restoreTraining(){try{const x=JSON.parse(localStorage.getItem(TRAINING_KEY)||'null');if(x&&Number.isFinite(x.started)&&Array.isArray(x.exercises))activeTraining=x}catch(e){activeTraining=null}}
function saveActiveTraining(){try{if(activeTraining)localStorage.setItem(TRAINING_KEY,JSON.stringify(activeTraining));else localStorage.removeItem(TRAINING_KEY)}catch(e){console.warn(e)}}
function elapsedTraining(){return activeTraining?Math.max(0,Math.floor(((finishingTraining?trainingEndedAt:Date.now())-activeTraining.started)/1000)):0}
function clockFormat(sec){return String(Math.floor(sec/3600)).padStart(2,'0')+':'+String(Math.floor(sec%3600/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
function restRemaining(){return restRunning?Math.max(0,Math.ceil((restEnd-Date.now())/1000)):restPaused}
function updateTrainingClocks(){document.querySelectorAll('[data-training-clock]').forEach(x=>x.textContent=clockFormat(elapsedTraining()));const remain=restRemaining();document.querySelectorAll('[data-rest-clock]').forEach(x=>x.textContent=String(Math.floor(remain/60)).padStart(2,'0')+':'+String(remain%60).padStart(2,'0'));if(restRunning&&remain===0){restRunning=false;restPaused=0;document.querySelectorAll('[data-rest-toggle]').forEach(x=>x.textContent='Erneut starten');document.querySelectorAll('[data-rest-status]').forEach(x=>x.textContent='Pause beendet');if(navigator.vibrate)navigator.vibrate([120,90,120]);toast('Pause beendet')}}
function chosenExercises(){return activeTraining?.exercises||[]}
function exerciseUsage(){const count={};for(const tr of S.trainings)for(const id of tr.exercises||[])count[id]=(count[id]||0)+1;return count}
function exerciseRecommendations(){const last={};for(const tr of S.trainings)for(const area of tr.areas||[])if(!last[area]||tr.date>last[area])last[area]=tr.date;return last}
function exerciseFiltered(){let a=EXERCISES.filter(x=>(exerciseCategory==='Alle'||x.category===exerciseCategory)&&x.name.toLocaleLowerCase('de').includes(exerciseSearch.toLocaleLowerCase('de')));const freq=exerciseUsage(),recent=exerciseRecommendations();if(exerciseSort==='frequent')a.sort((x,y)=>(freq[y.id]||0)-(freq[x.id]||0)||Number(y.favorite)-Number(x.favorite)||x.name.localeCompare(y.name,'de'));else if(exerciseSort==='suggested')a.sort((x,y)=>(recent[x.area]||'').localeCompare(recent[y.area]||'')||x.name.localeCompare(y.name,'de'));else a.sort((x,y)=>x.name.localeCompare(y.name,'de'));return a}
function trainingSessionView(){return `<header class="top"><div><div class="eyebrow">Dein Training</div><h1>Training läuft</h1></div><button data-action="sessionexit" aria-label="Training verlassen">×</button></header><main class="content"><section class="card session-clock"><div class="small muted">Trainingsdauer</div><div class="statbig" data-training-clock>${clockFormat(elapsedTraining())}</div><div class="small muted">Automatisch seit Trainingsbeginn</div></section><button class="session-library-link" data-action="sessionlibrary"><span><strong>Übungsbibliothek</strong><small>Übungen ansehen und auswählen</small></span><span aria-hidden="true">›</span></button>${chosenExercises().length?`<section class="card"><h2>Markierte Übungen (${chosenExercises().length})</h2><p class="small muted">${chosenExercises().map(id=>esc(EXERCISES.find(x=>x.id===id)?.name||id)).join(' · ')}</p></section>`:''}<div class="session-end-actions"><button class="btn full" data-action="sessionfinish">Training abschließen</button><button class="btn full secondary" data-action="sessiondiscard">Training verwerfen</button></div></main>`}
function compactRestTimer(){const remain=restRemaining(),done=!restRunning&&restPaused===0;return `<section class="rest-compact rest-standalone" aria-label="Pausentimer"><div class="rest-main"><strong>Pausentimer</strong><span class="rest-time" data-rest-clock>${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}</span><button class="rest-primary" data-action="resttoggle" data-rest-toggle>${restRunning?'Pause':done?'Erneut starten':'Start'}</button><button class="rest-reset" data-action="restreset" aria-label="Pausentimer zurücksetzen" title="Zurücksetzen">↺</button></div><div class="rest-presets">${[60,90,120].map(v=>`<button class="${restLength===v?'sel':''}" data-action="restlength:${v}">${v} s</button>`).join('')}</div><div class="rest-status small muted" data-rest-status>${done?'Pause beendet':''}</div></section>`}
function trainingLibraryView(){const e=EXERCISES.find(x=>x.id===exerciseFocus),marked=e&&chosenExercises().includes(e.id);return `<header class="top"><div><div class="eyebrow">Training · Übungsbibliothek</div><h1>${e?'Übung':'Übungen'}</h1></div><button data-action="sessionback">Zurück</button></header><main class="content ${e?'exercise-detail-content':''}">${e?`<section class="card exercise-detail-card"><div class="exercise-image">${exercisePhoto(e)}</div><div class="exercise-detail-inner"><h2>${esc(e.name)}</h2><p class="small muted exercise-muscles">${esc(e.muscles)}</p>${e.id==='ex-14'?'<p class="small muted exercise-warning">Foto zeigt eine verwandte enge Liegestütz-Variante, nicht exakt die Diamant-Handposition.</p>':''}<div class="exercise-hints-title">Darauf achten</div><ul class="exercise-tips">${e.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="btn full exercise-mark-button ${marked?'secondary':''}" data-action="exercisetoggle:${e.id}">${marked?'Markierung aufheben':'✓ Übung abschließen'}</button></div></section>${compactRestTimer()}`:`${compactRestTimer()}<div class="segment exercise-sort">${[['frequent','Häufig'],['suggested','Vorgeschlagen'],['all','Alle']].map(([id,n])=>`<button data-action="exercisesort:${id}" class="${exerciseSort===id?'sel':''}">${n}</button>`).join('')}</div><div class="field"><input id="exercisequery" placeholder="Übung suchen …" value="${esc(exerciseSearch)}" aria-label="Übung suchen"></div><div class="exercise-categories">${['Alle','Arme & Schultern','Rücken','Brust & Liegestütze','Beine & Gesäß','Bauch & Rumpf'].map(n=>`<button class="chip ${exerciseCategory===n?'sel':''}" data-action="exercisecategory:${n}">${n}</button>`).join('')}</div><section class="card" id="exercise-list">${exerciseListMarkup()}</section><p class="footnote">Vorschläge orientieren sich an dokumentierten Muskelgruppen, nicht an einem verpflichtenden Trainingsplan.</p>`}</main>`}
function exerciseListMarkup(){return exerciseFiltered().map(e=>`<div class="entry exercise-entry"><button class="exercise-name" data-action="exercisedetail:${e.id}">${EXERCISE_PHOTOS[e.id]?`<img class="exercise-thumb" src="${EXERCISE_PHOTOS[e.id][0]}" loading="lazy" alt="">`:``}<strong>${esc(e.name)}</strong><span class="small muted">${esc(e.muscles)}</span></button><button class="exercise-mark ${chosenExercises().includes(e.id)?'chosen':''}" aria-label="${chosenExercises().includes(e.id)?'Markierung entfernen':'Als trainiert markieren'}" data-action="exercisetoggle:${e.id}">${chosenExercises().includes(e.id)?'✓':'+'}</button></div>`).join('')||'<p class="small muted">Keine passenden Übungen.</p>'}
