async function migrateCatalogIcons(){
 const mapping=CATALOG_ICON_MIGRATIONS;
 let changed=false;
 for(const f of S.foods){
  const info=mapping[f.id];
  if(info && f.icon===info.old && info.new!==info.old){f.icon=info.new;changed=true;}
  else if(!f.id.startsWith('catalog-')&&!f.id.startsWith('starter-')){
   const appropriate=USER_ICON_SUGGESTIONS[f.name];
   if(appropriate && (f.icon==='🍽️'||(f.icon==='🥛'&&f.name==='Raspberry Lemonade')||(f.icon==='🥛'&&f.name==='Bananen Hafer Shake'))){f.icon=appropriate;changed=true;}
  }
 }
 for(const r of S.recipes){const official=RECIPE_CATALOG.find(x=>x.id===r.id);if(official && !r.icon){r.icon=official.icon;changed=true}}
 if(changed)await persist();
}

