// v0.10.1: Enrich existing local records without resetting user settings or diary data.
// A null sugar value means unknown; never treat it as zero.
async function migrateSugarCatalog(){
 let changed=false;
 const iconChanges=ICON_REVIEW_CHANGES;
 for(const store of ['foods','recipes']){
  for(const row of S[store]){
   const official=store==='foods'?FOOD_CATALOG_BY_ID.get(row.id):RECIPE_CATALOG_BY_ID.get(row.id);
   if(!official)continue;
   if(!Object.prototype.hasOwnProperty.call(row,'sugar')){
    row.sugar=official.sugar??null;
    row.sugarQuality=official.sugarQuality||'unbekannt';
    row.sugarSource=official.sugarSource||'';changed=true;
   }
   const correction=iconChanges[row.id];
   if(correction && row.icon===correction[0] && row.icon!==correction[1]){row.icon=correction[1];changed=true;}
   // Existing direct-recipe snapshots are copied when saved, not re-written in past diary entries.
   if(store==='recipes'&&row.items?.length===1&&row.directNutrition && row.items[0].snapshot){
    const f=row.items[0].snapshot;
    if(!Object.prototype.hasOwnProperty.call(f,'sugar') && row.sugar!=null){f.sugar=row.sugar;f.sugarQuality=row.sugarQuality;f.sugarSource=row.sugarSource;changed=true;}
    if(f.icon!==row.icon){f.icon=row.icon;changed=true;}
   }
  }
 }
 if(changed)await persist();
}

async function persist(){return new Promise((resolve,reject)=>{let t=db.transaction(STORES,'readwrite');for(let store of STORES){const o=t.objectStore(store);o.clear();const items=['settings','meta'].includes(store)?[{id:'main',value:S[store]}]:S[store];items.forEach(v=>o.put(v))}t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
const ordered=(a,field='date')=>[...a].sort((x,y)=>y[field].localeCompare(x[field]));const find=(a,id)=>a.find(x=>x.id===id);
