const secondaryMetric=()=>S.settings.secondaryMetric==='sugar'?'sugar':'protein',metricLabel=()=>secondaryMetric()==='sugar'?'Zucker':'Eiweiß',metricGoal=()=>secondaryMetric()==='sugar'?Number(S.settings.sugarGoal||90):Number(S.settings.proteinGoal||110),metricColor=()=>secondaryMetric()==='sugar'?'sugar':'protein';
