const latestW=()=>ordered(S.weights)[0];const actualWeight=()=>latestW()?.value??S.settings.startWeight;const phase=()=>S.phases[S.phases.length-1];const goalPercent=()=>{let p=phase();return p.target===p.start?0:pct(Math.sign(p.target-p.start)*(actualWeight()-p.start),Math.abs(p.target-p.start))};function weekStart(x){let d=new Date(x+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return iso(d)}function weekWeights(){let groups={};for(let w of S.weights){let key=weekStart(w.date);(groups[key]??=[]).push(w.value)}return Object.entries(groups).map(([date,v])=>({date,value:v.reduce((a,b)=>a+b,0)/v.length})).sort((a,b)=>a.date.localeCompare(b.date))}function weeklyTrend(){let a=weekWeights();if(a.length<2)return null;let recent=a.slice(-5);let first=new Date(recent[0].date+'T12:00:00'),last=new Date(recent.at(-1).date+'T12:00:00');let weeks=(last-first)/604800000;return weeks?((recent.at(-1).value-recent[0].value)/weeks):null}// Compare two consecutive 7-day mean weights, not two potentially noisy measurements.
