function nextDate(d){return new Date(d+'T12:00:00')};function remainingWeight(){return Math.max(0,goalDirection()*(phase().target-actualWeight()))}const goalDirection=(p=phase())=>Math.sign(p.target-p.start);const achieved=(p=phase(),w=actualWeight())=>goalDirection(p)!==0&&goalDirection(p)*(w-p.target)>=0;const progressWeight=(w=actualWeight(),p=phase())=>goalDirection(p)===0?0:goalDirection(p)*(w-p.start);
