function progressBar(value,goal,type=''){return `<div class="bar ${type}"><span style="width:${pct(value,goal)}%"></span></div>`}function weightCard(){if(!S.weights.length)return `<section class="card"><h2>Gewicht</h2><p class="small muted">Dein Ausgangsgewicht ist eingerichtet. Trage deine erste echte Gewichtsmessung ein, damit ein Verlauf entstehen kann.</p>${htmlButton('+ Gewicht eintragen','weight','full')}</section>`;let w=actualWeight(),p=phase(),diff=w-p.start,tr=sevenDayTrend(),ach=achieved(),positive=progressWeight(w)>0;return `<section class="card"><div class="split"><h2>Gewicht</h2></div><div class="split"><div><div class="statbig">${num(w)} <span class="small muted">kg</span></div><div class="small ${positive?'gain':''}">${diff>=0?'+':''}${num(diff)} kg seit Phasenstart</div></div><div style="text-align:right"><div class="small muted">Ziel</div><strong>${num(p.target)} kg</strong></div></div>${progressBar(progressWeight(w),Math.abs(p.target-p.start),ach?'green':'')}<div class="split small muted"><span>${num(p.start)} kg Start</span><span>${Math.round(goalPercent())} %</span><span>${num(p.target)} kg Ziel</span></div><div class="split" style="margin:14px 0"><div><div class="statlabel">7-Tage-Trend</div><strong class="${tr!==null&&goalDirection()*tr>=.05?'gain':''}">${trendText(tr)}</strong>${tr===null?'<div class="small muted">Zwei 7-Tage-Zeiträume nötig</div>':''}</div><div style="text-align:right"><div class="statlabel">Bis zum Ziel</div><strong>${num(remainingWeight())} kg</strong></div></div>${htmlButton('+ Gewicht eintragen','weight','full')}</section>`}
