  const status=isSugar?`<span class="small muted">${!hasNutritionData(today())?'Noch nichts erfasst':complete?`Richtwert um ${num(-remaining,1)} g überschritten`:`${num(remaining,1)} g bis Richtwert`}</span>`:complete?`<span class="goal-reached" aria-label="Tagesziel erreicht">${appIcon('check',15)} Ziel erreicht${remaining<0?' · +'+num(-remaining,unit==='kcal'?0:1)+' '+unit:''}</span>`:`<span class="small muted">${!hasNutritionData(today())?'Noch nichts erfasst':`Noch ${num(remaining,unit==='kcal'?0:1)} ${unit}`}</span>`;
