function balanceLabel(balance){return balance>0?'Überschuss':balance<0?'Defizit':'Ausgeglichen'}
function nutritionLegend(metric){if(metric==='sugar')return `<div class="energy-legend"><div class="energy-legend-row"><span><i class="energy-legend-dash" style="border-color:var(--sugar)"></i>Zucker-Richtwert</span><span><i style="background:var(--sugar)"></i>Gesamtzucker</span></div><div class="energy-legend-row">Heute (vorläufig) · kein Mindestziel</div></div>`;if(metric==='energy')return `<div class="energy-legend energy-legend-energy"><div class="energy-legend-row"><span><i class="energy-legend-dash"></i>Geplantes Kalorienziel</span><span><i class="energy-legend-zero"></i>0 Erhaltungsbedarf</span></div><div class="energy-legend-row energy-legend-tight"><span><i class="energy-legend-success"></i>Tagesziel erreicht</span><span><i class="energy-legend-neutral"></i>Tagesziel nicht erreicht</span></div><div class="energy-legend-row"><span><i class="energy-legend-today"></i>Heute (vorläufig)</span></div></div>`;return `<div class="energy-legend energy-legend-protein"><div class="energy-legend-row"><span><i class="energy-legend-dash energy-legend-dash-protein"></i>Geplantes Eiweißziel</span></div><div class="energy-legend-row energy-legend-tight"><span><i class="energy-legend-protein-success"></i>Ziel erreicht</span><span><i class="energy-legend-protein-neutral"></i>Ziel nicht erreicht</span></div><div class="energy-legend-row"><span><i class="energy-legend-today-protein"></i>Heute (vorläufig)</span></div></div>`}
function nutritionGraph(days,metric){
 const records=days.map((d,i)=>({d,i,v:!d.has?null:metric==='sugar'&&d.totals.sugarIncomplete&&d.totals.sugar===0?null:metric!=='energy'?d.totals[metric]:d.balance}));
 const vals=records.filter(x=>x.v!==null&&Number.isFinite(x.v)).map(x=>x.v);
 if(!vals.length)return '<p class="small muted">Für diesen Zeitraum sind noch keine auswertbaren Daten vorhanden.</p>';
 const W=360,H=215,topY=23,botY=168,left=45,right=12,slot=(W-left-right)/days.length;
 const targetDaily=days.map(d=>d.maintenance!==null?S.settings.kcalGoal-d.maintenance:null);
 const targets=metric==='energy'?targetDaily.filter(x=>x!==null&&Number.isFinite(x)):[];
 let hi,lo;
 if(metric==='energy'){
  const samples=[...vals,...targets,0];
  const highest=Math.max(0,...samples),lowest=Math.min(0,...samples);
  hi=Math.ceil(Math.max(100,highest*1.12,(highest-lowest)*.07)/100)*100;
  lo=-Math.ceil(Math.max(100,-lowest*1.12,(highest-lowest)*.07)/100)*100;
 }else{hi=Math.ceil(Math.max(metric==='sugar'?S.settings.sugarGoal:S.settings.proteinGoal,...vals,1)*1.15/20)*20;lo=0}
 const y=v=>topY+(hi-v)/(hi-lo)*(botY-topY),zeroY=y(0);
 const grid=metric==='energy'?[lo,0,hi]:[0,hi/2,hi];
 const guides=grid.map(v=>`<line x1="${left}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="${v===0&&metric==='energy'?'var(--muted)':'var(--line)'}" stroke-width="${v===0&&metric==='energy'?1.7:1}"/><text x="${left-7}" y="${y(v)+4}" font-size="10" text-anchor="end" fill="var(--muted)">${v>0?'+':''}${num(v,0)}</text>`).join('');
 // Die Zielgerade zeigt die Differenz zwischen Kalorienziel und Erhaltungsbedarf.
 // Historische Bedarfsschätzungen können sich ändern; in dem Fall verbindet eine gestrichelte Linie die Tagesziele.
 const target=metric!=='energy'?`<line x1="${left}" x2="${W-right}" y1="${y(metric==='sugar'?S.settings.sugarGoal:S.settings.proteinGoal)}" y2="${y(metric==='sugar'?S.settings.sugarGoal:S.settings.proteinGoal)}" stroke="var(--${metric==='sugar'?'sugar':'protein'})" stroke-width="1.6" stroke-dasharray="5 4"/>`:targets.length?`<polyline points="${days.map((d,i)=>targetDaily[i]===null?null:`${(left+(i+.5)*slot).toFixed(1)},${y(targetDaily[i]).toFixed(1)}`).filter(Boolean).join(' ')}" fill="none" stroke="var(--blue)" stroke-width="1.7" stroke-dasharray="5 4" stroke-linejoin="round"><title>Geplantes Ziel gegenüber Erhaltungsbedarf</title></polyline>`:'';
 const bars=records.map(({d,i,v})=>{
  if(v===null||!Number.isFinite(v))return '';
  const x=left+i*slot+slot*.18,bw=Math.max(1.8,slot*.64),yv=y(v),h=Math.max(2,Math.abs(yv-zeroY)),from=metric==='energy'?Math.min(yv,zeroY):yv;
  const planned=targetDaily[i];
  const meetsGoal=metric==='protein'?v>=S.settings.proteinGoal-0.001:metric==='sugar'?v<=S.settings.sugarGoal+0.001:planned!==null&&(goalDirection()===0?Math.abs(v-planned)<=100:goalDirection()*(v-planned)>=-0.001);
  const color=metric==='sugar'?'var(--sugar)':metric==='protein'?(meetsGoal?'var(--protein)':'var(--protein-neutral)'):meetsGoal?'var(--success)':'var(--energy-neutral)';
  const provisional=d.date===today();
  const label=metric==='sugar'?`${num(v,1)} g Zucker`:metric==='protein'?`${num(v,1)} g Eiweiß`:`${v>0?'+':''}${num(v,0)} kcal gegenüber Erhaltungsbedarf${planned===null?'':`; Ziel: ${planned>0?'+':''}${num(planned,0)} kcal`}`;
  return `<rect x="${x.toFixed(2)}" y="${from.toFixed(2)}" width="${bw.toFixed(2)}" height="${h.toFixed(2)}" rx="${Math.min(3,bw/3)}" fill="${color}" opacity="${provisional?.46:1}"><title>${esc(dateDisplay(d.date))}${provisional?' (heute, vorläufig)':''}: ${esc(label)}</title></rect>`
 }).join('');
 const marks=days.length===7?days.map((d,i)=>[d,i]):[0,Math.floor((days.length-1)/2),days.length-1].map(i=>[days[i],i]);
 const ticks=marks.map(([d,i])=>`<text x="${left+(i+.5)*slot}" y="192" text-anchor="middle" font-size="11" fill="var(--muted)">${esc(new Date(d.date+'T12:00:00').toLocaleDateString('de-DE',days.length===7?{weekday:'short'}:{day:'2-digit',month:'2-digit'}))}${d.date===today()?'*':''}</text>`).join('');
 return `<svg viewBox="0 0 ${W} ${H}" class="energy-chart" role="img" aria-label="${metric==='sugar'?'Täglich erfasster Gesamtzucker':metric==='protein'?'Täglich erfasstes Eiweiß':'Geschätzte Energiebilanz mit Nulllinie, Zielüberschuss bzw. Zieldefizit und gedämpftem heutigen Balken'}">${guides}${bars}${target}${ticks}</svg>`
}
function nutritionView(){
 const current=today(),weekDates=Array.from({length:nutritionPeriod},(_,i)=>shift(current,i-(nutritionPeriod-1)));
 const allEntries=[...S.meals,...S.drinks].map(x=>x.date).filter(Boolean).sort();
 const firstRecorded=allEntries[0]||null;
 const week=weekDates.map(d=>({date:d,has:hasNutritionData(d),maintenance:maintenanceAt(d),totals:dayTotals(d)}));
 // Der laufende Tag wird nur gezeichnet, aber nicht in die abgeschlossene Wochenbilanz eingerechnet.
 const finished=week.filter(d=>d.date<current&&(!firstRecorded||d.date>=firstRecorded));
 const comparable=finished.filter(d=>d.has&&d.maintenance!==null);
 const balance=comparable.reduce((acc,d)=>acc+d.totals.kcal-d.maintenance,0);
 const proteinDays=finished.filter(d=>d.has);
 const avgProtein=proteinDays.length?proteinDays.reduce((sum,d)=>sum+d.totals[secondaryMetric()],0)/proteinDays.length:null;
 const missingMaintenance=!(S.settings.maintenanceKcal>0),days=nutritionDays(nutritionPeriod);
 const positive=goalDirection()!==0&&goalDirection()*balance>0;
 const balanceLine=missingMaintenance?`<div class="energy-setup"><strong>Erhaltungsbedarf fehlt noch</strong><p class="small muted">Berechne ihn einmal in den Einstellungen. Dein bisheriges Kalorienziel bleibt dabei unverändert, bis du eine neue Empfehlung ausdrücklich übernimmst.</p><button class="btn secondary" data-action="caloriecalc">Erhaltungsbedarf berechnen →</button></div>`:`<div class="energy-main"><div><div class="statlabel">Bilanz bisheriger Tage</div><div class="energy-number ${positive?'gain':''}">${comparable.length?`${balance>0?'+':''}${num(balance,0)}`:'–'} <span>kcal</span></div><div class="small muted">${comparable.length?`${comparable.length} ${comparable.length===1?'Tag':'Tage'} mit Bilanz`:'Noch keine vergangenen Tage mit Einträgen'}</div><div class="energy-daily-average">${comparable.length?`Ø ${balance/comparable.length>0?'+':''}${num(balance/comparable.length,0)} kcal/Tag`:'Ø kcal/Tag: –'}</div></div><div><div class="statlabel">Ø ${metricLabel()} · bisherige Tage</div><div class="energy-number">${avgProtein!==null?num(avgProtein,1):'–'} <span>g/Tag</span></div><div class="small muted">${avgProtein!==null?`${Math.round(avgProtein/Math.max(1,metricGoal())*100)} % des ${secondaryMetric()==='sugar'?'Zucker-Richtwerts':'Eiweißziels'}`:'Noch keine vergangenen Tage'}</div></div></div>`;
 const legend=nutritionLegend(nutritionMetric);
 const diaryTotals=dayTotals(date);
 const diaryFooter=`<div class="diary-totals"><div class="diary-total-title">Gesamt an diesem Tag</div><div class="diary-total-pair"><div><span>Kalorien gesamt</span><strong>${num(diaryTotals.kcal,0)} <small>kcal</small></strong></div><div><span>${metricLabel()} gesamt</span><strong>${num(diaryTotals[secondaryMetric()],1)} <small>g</small></strong></div></div></div>`;
 return `<header class="top"><div><div class="eyebrow">Deine Energiebilanz</div><h1>Ernährung</h1></div><button data-action="settings" aria-label="Einstellungen">${appIcon('settings',19)}</button></header><main class="content"><section class="card energy-overview"><div class="split"><h2>Letzte ${nutritionPeriod} Tage</h2><span class="small muted">${dateDisplay(weekDates[0])}–${dateDisplay(weekDates[6])}</span></div>${balanceLine}<div class="hr"></div><div class="split"><h2>${nutritionMetric==='energy'?'Energiebilanz':nutritionMetric==='sugar'?'Zuckerverlauf':'Eiweißverlauf'}</h2></div><div class="segment energy-tabs"><button class="${nutritionMetric==='energy'?'sel':''}" data-action="nutrmetric:energy">Kalorien</button><button class="${nutritionMetric===secondaryMetric()?'sel':''}" data-action="nutrmetric:${secondaryMetric()}">${metricLabel()}</button></div><div class="segment energy-tabs">${[[7,'7 Tage'],[30,'30 Tage'],[90,'90 Tage']].map(([v,l])=>`<button class="${nutritionPeriod===v?'sel':''}" data-action="nutrperiod:${v}">${l}</button>`).join('')}</div>${nutritionGraph(days,nutritionMetric)}${legend}</section><div class="section-title">Ernährungstagebuch</div><div class="daynav"><button data-action="day:-1" aria-label="Vorheriger Tag">‹</button><button class="dateclick" type="button" data-action="pickdate" aria-label="Datum im Kalender auswählen"><strong>${esc(dateText(date))}</strong><span>${date.slice(0,4)} ${appIcon('calendar',15)}</span></button><button data-action="day:1" aria-label="Nächster Tag">›</button></div><input type="date" id="date-picker" value="${date}" style="position:absolute;opacity:0;width:1px;height:1px;pointer-events:none" aria-label="Datum"><section class="card">${nutritionEntries(date)}${diaryFooter}</section></main>`
}

function lineChart(points,daily=[],unit='kg',period='3',type='weight'){
 let now=new Date(today()+'T12:00:00'),end=now.getTime(),start;
 if(period==='1'){let x=new Date(now);x.setMonth(x.getMonth()-1);start=x.getTime()}
 else if(period==='3'||period==='6'){let x=new Date(now);x.setMonth(x.getMonth()-Number(period));start=x.getTime()}
 else start=-Infinity;
 if(type==='weight'){
  const all=ordered(S.weights).reverse();if(!all.length)return '<div class="hint">Noch keine Messwerte vorhanden.</div>';
  start=Math.max(start,nextDate(all[0].date).getTime());
  const data=all.filter(p=>{const t=nextDate(p.date).getTime();return t>=start&&t<=end});
  if(!data.length)return '<div class="hint">Noch keine Messwerte in diesem Zeitraum vorhanden.</div>';
  const smoothEligible=all.length>=3&&(nextDate(all.at(-1).date)-nextDate(all[0].date))>=7*86400000;
  const prediction=weightForecast();const forecastEligible=!!prediction&&period!=='1';
  const smooth=showSmooth&&smoothEligible?smoothedWeights(all).filter(p=>p.date>=data[0].date&&p.date<=data.at(-1).date):[];
  const graphStart=start;
  const futureEnd=forecastEligible&&showForecast?Math.min(nextDate(prediction.date).getTime(),end+90*86400000):end;
  const graphEnd=Math.max(end,futureEnd,start+86400000);
  const values=data.map(p=>p.value);const lastData=data.at(-1),lastDataMs=nextDate(lastData.date).getTime();
  const projected=forecastEligible&&showForecast?prediction.endWeight+prediction.slope*(Math.min(futureEnd,nextDate(prediction.date).getTime())-lastDataMs)/(7*86400000):null;
  const axisValues=[...values,...smooth.map(p=>p.value),...(projected!==null?[projected,prediction.endWeight]:[])];
  const rawMin=Math.min(...axisValues),rawMax=Math.max(...axisValues),padding=Math.max((rawMax-rawMin)*.13,.35),lo=rawMin-padding,hi=rawMax+padding;
  const Xms=t=>47+(t-graphStart)/(graphEnd-graphStart)*292;
  const X=p=>Xms(nextDate(p.date).getTime());
  const Y=v=>163-(v-lo)/(hi-lo)*125;
  const poly=pts=>pts.map((p,i)=>`${i?'L':'M'}${X(p).toFixed(2)},${Y(p.value).toFixed(2)}`).join(' ');
  const grid=[0,1,2,3].map(i=>{const v=lo+(hi-lo)*(3-i)/3,y=38+i*125/3;return `<line x1="44" x2="343" y1="${y}" y2="${y}" class="chartgrid"/><text x="39" y="${y+4}" class="chartlabel" text-anchor="end">${num(v,1)}</text>`}).join('');
  const labels=[0,.5,1].map(f=>{const t=new Date(graphStart+f*(graphEnd-graphStart));return `<text x="${47+f*292}" y="191" text-anchor="middle" class="chartlabel">${t.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</text>`}).join('');
  const last=data.at(-1),lastMs=nextDate(last.date).getTime();
  // Forecast follows fitted multiweek slope. Clip to visible Y range, avoiding chart distortion.
  let future='';if(forecastEligible&&showForecast&&futureEnd>lastMs){const xEnd=Math.min(futureEnd,nextDate(prediction.date).getTime());const projection=prediction.endWeight+prediction.slope*(xEnd-lastMs)/(7*86400000);const clip=v=>Y(v);future=`<rect x="${Xms(lastMs)}" y="38" width="${Math.max(0,Xms(graphEnd)-Xms(lastMs))}" height="125" class="chart-future"/><line x1="${Xms(lastMs)}" x2="${Xms(lastMs)}" y1="38" y2="163" class="chart-future-edge"/><path d="M${Xms(lastMs)},${clip(prediction.endWeight)} L${Xms(xEnd)},${clip(projection)}" class="chart-prediction"/><text x="${Math.min(333,Xms(lastMs)+6)}" y="32" class="chartlabel" font-size="9">Prognose</text>`}
  const dots=data.map((p,i)=>`<circle cx="${X(p)}" cy="${Y(p.value)}" r="${i===data.length-1?4.7:3.2}" fill="var(--blue)" stroke="var(--surface)" stroke-width="1.5"><title>${esc(dateDisplay(p.date))}: ${num(p.value)} kg</title></circle>`).join('');
  return `<div class="chart-average-label">${data.length} ${data.length===1?'Messwert':'Messwerte'} · letzter Wert: ${num(last.value)} kg</div><svg class="chart" viewBox="0 0 360 205" role="img" aria-label="Tatsächliche Gewichtsmessungen${smooth.length?', geglätteter Verlauf':''}${future?', optionale Prognose':''}">${grid}${future}${data.length>1?`<path d="${poly(data)}" class="chartline"/>`:''}${smooth.length>1?`<path d="${poly(smooth)}" class="chart-smooth"/>`:''}${dots}${labels}</svg><div class="legend" style="margin:12px 0"><span><i></i>Messwerte</span>${smooth.length>1?'<span><i class="smooth"></i>7-Tage-Glättung</span>':''}${future?'<span><i class="prediction"></i>Prognose</span>':''}</div><div class="chart-options"><label class="small muted"><input type="checkbox" id="smoothtoggle" ${showSmooth?'checked':''} ${smoothEligible?'':'disabled'}> Geglätteten Verlauf anzeigen</label><label class="small muted"><input type="checkbox" id="forecasttoggle" ${showForecast?'checked':''} ${forecastEligible?'':'disabled'}> Prognose anzeigen</label></div>${!smoothEligible?'<p class="footnote">Glättung ab 3 Messungen über mindestens 7 Tage verfügbar.</p>':''}`;
 }
 // Each body measurement starts at its own first actual measurement, as the weight graph does.
 const all=points.filter(p=>p&&p.date&&Number.isFinite(Number(p.value))).sort((a,b)=>a.date.localeCompare(b.date));
 if(!all.length)return '<div class="hint">Noch keine Messwerte vorhanden.</div>';
 const firstTime=nextDate(all[0].date).getTime();
 start=Math.max(start,firstTime);
 const data=all.filter(p=>{const t=nextDate(p.date).getTime();return t>=start&&t<=end});
 if(!data.length)return '<div class="hint">Noch keine Messwerte in diesem Zeitraum vorhanden.</div>';
 const graphStart=start,graphEnd=Math.max(end,start+86400000);
 const vals=data.map(p=>Number(p.value)),lo0=Math.min(...vals),hi0=Math.max(...vals);
 const pad=Math.max((hi0-lo0)*.3,1),lo=lo0-pad,hi=hi0+pad;
 const X=p=>47+(nextDate(p.date).getTime()-graphStart)/(graphEnd-graphStart)*292;
 const Y=v=>163-(v-lo)/(hi-lo)*125;
 const grid=[0,1,2,3].map(i=>{let v=lo+(hi-lo)*(3-i)/3,y=38+i*125/3;return `<line x1="44" x2="343" y1="${y}" y2="${y}" class="chartgrid"/><text x="39" y="${y+4}" class="chartlabel" text-anchor="end">${num(v,1)}</text>`}).join('');
 // A single measurement must show its actual date, not three invented earlier month labels.
 const labelDates=data.length===1?[{date:data[0].date,x:X(data[0])}]:[0,.5,1].map(f=>({date:iso(new Date(graphStart+f*(graphEnd-graphStart))),x:47+f*292}));
 const labels=labelDates.map(p=>`<text x="${p.x.toFixed(2)}" y="191" text-anchor="${data.length===1?'start':p.x>310?'end':p.x<60?'start':'middle'}" class="chartlabel">${esc(new Date(p.date+'T12:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'}))}</text>`).join('');
 const path=data.map((p,i)=>`${i?'L':'M'}${X(p).toFixed(2)},${Y(p.value).toFixed(2)}`).join(' ');
 const dots=data.map(p=>`<circle cx="${X(p).toFixed(2)}" cy="${Y(p.value).toFixed(2)}" r="4.2" fill="var(--blue)" stroke="var(--surface)" stroke-width="1.5"><title>${esc(dateDisplay(p.date))}: ${num(p.value,1)} cm</title></circle>`).join('');
 return `<svg class="chart" viewBox="0 0 360 205" role="img" aria-label="${data.length===1?'Eine Körpermaßmessung':'Körpermaßverlauf'} in ${unit}, ab erster Messung">${grid}${data.length>1?`<path d="${path}" class="chartline"/>`:''}${dots}${labels}</svg>${data.length===1?'<p class="footnote">Erste Messung. Ein Verlauf entsteht mit weiteren Messungen.</p>':''}`;
}

function measurementChart(k,label){let data=ordered(S.measurements).reverse().filter(x=>x[k]!==undefined&&x[k]!==null).map(x=>({date:x.date,value:x[k]}));let latest=data.at(-1),first=data[0],delta=latest&&first?latest.value-first.value:0;return `<section class="card"><div class="split"><h2>${label}</h2><div style="text-align:right"><strong>${latest?num(latest.value):'–'} cm</strong><div class="small muted">${latest&&data.length>1?(delta>0?'+':'')+num(delta)+' cm seit Beginn':'Noch kein Vergleichswert'}</div></div></div>${lineChart(data,[],'cm',range,'measure')}</section>`}
function progressView(){if(!S.weights.length&&progressTab==='weight')return `<header class="top"><div><div class="eyebrow">Deine Entwicklung</div><h1>Fortschritt</h1></div><button data-action="settings" aria-label="Einstellungen">${appIcon('settings',19)}</button></header><main class="content"><div class="segment"><button class="sel" data-action="progress:weight">Gewicht</button><button data-action="progress:measure">Körpermaße</button></div><section class="card"><h2>Dein Gewichtsverlauf beginnt hier</h2><p class="small muted">Dein Ziel ist eingerichtet. Mit der ersten Gewichtsmessung beginnt der persönliche Verlauf – ohne erfundene Trends oder Prognosen.</p>${htmlButton('+ Gewicht eintragen','weight','full')}</section></main>`;let actual=ordered(S.weights).reverse(),phaseEnergy=nutritionRangeSummary(phase().started||today(),shift(today(),-1)),trendEnergy=nutritionRangeSummary(shift(today(),-7),shift(today(),-1)),weightTrend=sevenDayTrend();return `<header class="top"><div><div class="eyebrow">Deine Entwicklung</div><h1>Fortschritt</h1></div><button data-action="settings" aria-label="Einstellungen">${appIcon('settings',19)}</button></header><main class="content"><div class="segment"><button class="${progressTab==='weight'?'sel':''}" data-action="progress:weight">Gewicht</button><button class="${progressTab==='measure'?'sel':''}" data-action="progress:measure">Körpermaße</button></div>${progressTab==='weight'?`${achieved()?`<section class="successbox" style="margin-bottom:13px"><strong>🏆 Zielgewicht erreicht!</strong><p class="small">Dein bisheriger Verlauf bleibt erhalten. Du kannst ein neues Ziel definieren oder das aktuelle beibehalten.</p><button class="btn sm" data-action="nextgoal">Neues Ziel festlegen</button></section>`:''}<section class="card"><div class="split"><div><div class="statlabel">Seit Phasenstart</div><div class="statnum ${progressWeight()>0?'gain':''}">${S.weights.length>=2?`${actualWeight()-phase().start>0?'+':''}${num(actualWeight()-phase().start)} kg`:'–'}</div><div class="progress-energy-hint ${phaseEnergy.days?balanceTone(phaseEnergy.balance):'muted'}">${phaseEnergy.days?`Bilanz: ${phaseEnergy.balance>0?'+':''}${num(phaseEnergy.balance,0)} kcal`:'Noch keine kcal-Bilanz'}</div></div><div style="text-align:right"><div class="statlabel">7-Tage-Trend</div><div class="statnum">${weightTrend===null?'–':`${weightTrend>=0?'+':''}${num(weightTrend,1)} kg`}</div><div class="small muted">${weightTrend===null?'Zwei 7-Tage-Zeiträume nötig':Math.abs(weightTrend)<.05?'→ Stabil':weightTrend>0?'↗ Ø gegenüber Vorwoche':'↘ Ø gegenüber Vorwoche'}</div><div class="progress-energy-hint ${trendEnergy.days?balanceTone(trendEnergy.balance):'muted'}">${trendEnergy.days?`Bilanz: ${trendEnergy.balance>0?'+':''}${num(trendEnergy.balance,0)} kcal`:'Noch keine kcal-Bilanz'}</div></div></div></section><section class="card"><div class="split"><h2>Gewichtsverlauf</h2><span class="muted small">Messwerte & Verlauf</span></div><div class="segment">${[['1','1 M'],['3','3 M'],['6','6 M'],['all','Alles']].map(([v,l])=>`<button class="${range===v?'sel':''}" data-action="range:${v}">${l}</button>`).join('')}</div>${lineChart(actual,[], 'kg',range)}${forecast()}</section>${combinedAnalysisView()}<section class="card"><h2>Zielphasen</h2>${S.phases.map((p,i)=>`<div class="phase"><strong>Phase ${i+1}: ${num(p.start)} → ${num(p.target)} kg</strong><div class="small muted">${p.reached?'Erreicht am '+dateDisplay(p.reached):i===S.phases.length-1?'Aktuelles Ziel':'Abgeschlossen'}</div></div>`).join('')}</section>`:`<div class="btnrow" style="margin-bottom:13px">${htmlButton('+ Körpermaße erfassen','measure','full')}</div><div class="segment">${[['1','1 M'],['3','3 M'],['6','6 M'],['all','Alles']].map(([v,l])=>`<button class="${range===v?'sel':''}" data-action="range:${v}">${l}</button>`).join('')}</div>${measurementChart('waist','Taille')}${measurementChart('chest','Brust')}${measurementChart('arm','Oberarm')}<section class="card"><h2>Messungen</h2>${ordered(S.measurements).map(m=>`<div class="entry"><div><strong>${dateDisplay(m.date)}</strong><div class="meta">${[['waist','Taille'],['chest','Brust'],['arm','Oberarm']].filter(([k])=>m[k]!=null).map(([k,l])=>`${l}: ${num(m[k])} cm`).join(' · ')}</div></div><button class="btn sm secondary" data-action="edit:measure:${m.id}">Bearbeiten</button></div>`).join('')||'<p class="small muted">Noch keine Messungen.</p>'}</section>`}</main>`}
function forecast(){
 const p=weightForecast();
 if(!p)return '<div class="progress-forecast-note muted">Zielprognose nach mindestens 4 Wochen und 8 Gewichtsmessungen bei stabilem Trend verfügbar.</div>';
 const month=nextDate(p.date).toLocaleDateString('de-DE',{month:'long',year:'numeric'});
 return `<div class="progress-forecast-note"><strong>${num(phase().target)} kg möglicherweise im ${month}</strong><span class="muted">Unverbindliche Schätzung bei gleichbleibendem Trend.</span></div>`;
}
let comparisonPeriod=28;
function combinedAnalysisView(){
 const end=shift(today(),-1),start=shift(end,-comparisonPeriod+1);
 const energy=nutritionRangeSummary(start,end),weightRows=S.weights.filter(w=>w.date>=start&&w.date<=end).sort((a,b)=>a.date.localeCompare(b.date));
 const first=weightRows.filter(w=>w.date<=shift(start,6)),last=weightRows.filter(w=>w.date>=shift(end,-6));
 const mean=rows=>rows.length?rows.reduce((sum,w)=>sum+Number(w.value),0)/rows.length:null;
 const before=mean(first),after=mean(last),delta=before===null||after===null?null:after-before;
 const average=energy.days?energy.balance/energy.days:null,coverage=energy.days/comparisonPeriod;
 const ready=first.length>=2&&last.length>=2&&energy.days>=Math.ceil(comparisonPeriod*.7);
 const finding=!ready?'Für einen belastbaren Vergleich brauchen wir mindestens zwei Gewichtsmessungen in der ersten und letzten Woche und an mindestens 70 % der Tage Ernährungseinträge.':Math.abs(delta)<.1?'Das Gewicht ist in diesem Zeitraum weitgehend stabil geblieben.':Math.sign(average)===Math.sign(delta)?'Kalorienbilanz und Gewichtsveränderung zeigen im gleichen Zeitraum in dieselbe Richtung.':'Kalorienbilanz und Gewicht zeigen unterschiedliche Richtungen; Schätzbedarf und nicht vollständig erfasste Mahlzeiten können dazu beitragen.';
 if(!energy.days&&!weightRows.length)return `<section class="card combined-analysis"><h2>Kalorien &amp; Gewicht im Vergleich</h2><p class="small muted">Hier erscheint ein Vergleich, sobald Ernährung und Gewicht über mehrere Wochen erfasst wurden.</p></section>`;
 return `<section class="card combined-analysis"><div class="split"><h2>Kalorien &amp; Gewicht im Vergleich</h2></div><div class="segment">${[[28,'4 Wochen'],[56,'8 Wochen'],[84,'12 Wochen']].map(([v,l])=>`<button class="${comparisonPeriod===v?'sel':''}" data-action="compareperiod:${v}">${l}</button>`).join('')}</div><div class="analysis-metrics"><div><div class="statlabel">Ø Kalorienbilanz/Tag</div><div class="statnum ${average!==null?balanceTone(average):'muted'}">${average===null?'–':`${average>=0?'+':''}${num(average,0)}`} <small>kcal</small></div><div class="small muted">${energy.days} von ${comparisonPeriod} Tagen erfasst</div></div><div><div class="statlabel">Gewichtsänderung</div><div class="statnum ${delta!==null&&delta>0?'gain':''}">${delta===null?'–':`${delta>=0?'+':''}${num(delta,1)}`} <small>kg</small></div><div class="small muted">Vergleich der ersten/letzten 7 Tage</div></div></div><div class="analysis-finding"><strong>${ready?'Einordnung':'Noch nicht ausreichend Daten'}</strong><p>${finding}</p></div>${ready?'<p class="footnote">Die Kalorienbilanz basiert auf erfassten Tagen; sie kann unvollständig sein. Der Vergleich zeigt einen Zusammenhang, keine Kausalität.</p>':''}</section>`;
}

function trainingView(){let ws=weekStart(today()),days=Array.from({length:7},(_,i)=>shift(ws,i)),inWeek=S.trainings.filter(t=>t.date>=ws&&t.date<=days[6]);return `<header class="top"><div><div class="eyebrow">Bewegung festhalten</div><h1>Training</h1></div><button data-action="settings" aria-label="Einstellungen">${appIcon('settings',19)}</button></header><main class="content"><section class="card"><div class="split"><h2>Diese Woche</h2><strong>${inWeek.length} ${inWeek.length===1?'Einheit':'Einheiten'}</strong></div><div class="weekdays">${days.map(d=>`<div class="weekday ${inWeek.some(t=>t.date===d)?'done':''}">${new Date(d+'T12:00:00').toLocaleDateString('de-DE',{weekday:'short'})}<b>${Number(d.slice(-2))}</b>${inWeek.some(t=>t.date===d)?'●':'·'}</div>`).join('')}</div>${htmlButton(activeTraining?'Training fortsetzen':'Training starten','sessionstart','full')}</section><div class="section-title">Trainingstagebuch</div><section class="card">${ordered(S.trainings).map(t=>`<div class="entry tappable" data-action="expand:training:${t.id}"><div class="grow"><strong>${dateDisplay(t.date)}</strong><div class="meta">${esc(t.duration)} Min. · ${esc(t.areas.join(', '))}</div><div class="details" id="detail-${t.id}" hidden>${t.note?`<p>${esc(t.note)}</p>`:''}${t.exercises?.length?`<p class="small muted">Übungen: ${t.exercises.map(id=>esc(EXERCISES.find(e=>e.id===id)?.name||id)).join(', ')}</p>`:''}<div class="btnrow"><button class="btn sm secondary" data-action="edit:training:${t.id}">Bearbeiten</button><button class="btn sm secondary danger" data-action="delete:training:${t.id}">Löschen</button></div></div></div><span class="muted">›</span></div>`).join('')||'<p class="small muted">Noch keine Trainingseinträge.</p>'}</section></main>`}
let metricSwipeSuppressUntil=0;let onboardingStep=0;
let onboardingDraft={start:'',target:'',sex:'male',age:'',height:'',activity:'1.375',change:'250',kcal:'',protein:'90',sugar:'90',secondaryMetric:'protein'};
function setupCapture(){const fields=['start','target','age','height','activity','change','kcal','protein','sugar','secondaryMetric'];for(const k of fields){const e=$('#setup-'+k);if(e)onboardingDraft[k]=e.value}try{localStorage.setItem('weight-app-setup-draft-v1',JSON.stringify({step:onboardingStep,data:onboardingDraft}))}catch(e){}return onboardingDraft}
function onboardingEstimate(){let d=onboardingDraft,base=10*n(d.start)+6.25*n(d.height)-5*n(d.age)+(d.sex==='female'?-161:5),maintenance=base*n(d.activity);return {maintenance:Math.round(maintenance/25)*25,kcal:Math.round((maintenance+Math.sign(n(d.target)-n(d.start))*n(d.change))/25)*25}}
function onboardingView(){let d=onboardingDraft,estimate=onboardingEstimate(),step=onboardingStep,field=(id,title,value,mode='decimal')=>`<div class="field"><label for="setup-${id}">${title}</label><input id="setup-${id}" inputmode="${mode}" value="${esc(value||'')}" required></div>`;
 const goal=step===0?`<h2>Dein Ziel</h2><p class="small muted">Wir verwenden keine fremden Beispielgewichte. Du kannst zunehmen, abnehmen oder dein Gewicht halten.</p><div class="twocolfields">${field('start','Ausgangsgewicht (kg)',d.start)}${field('target','Zielgewicht (kg)',d.target)}</div><p class="small muted">Für Gewichtserhaltung wähle in beiden Feldern denselben Wert.</p>`:'';
 const profile=step===1?`<h2>Dein Kalorienbedarf</h2><div class="field"><label>Berechnungsformel</label><div class="segment"><button type="button" class="${d.sex==='male'?'sel':''}" data-action="setupsex:male">Männlich</button><button type="button" class="${d.sex==='female'?'sel':''}" data-action="setupsex:female">Weiblich</button></div></div><div class="twocolfields">${field('age','Alter (Jahre)',d.age,'numeric')}${field('height','Körpergröße (cm)',d.height)}</div><div class="field"><label for="setup-activity">Aktivität im Alltag</label><select id="setup-activity">${[['1.2','Überwiegend sitzend'],['1.375','Leicht aktiv'],['1.55','Mäßig aktiv'],['1.725','Sehr aktiv']].map(([v,l])=>`<option value="${v}" ${v===d.activity?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="setup-change">Gewünschter Zuschlag/Abschlag</label><select id="setup-change">${[['150','Behutsam · 150 kcal'],['250','Moderat · 250 kcal'],['400','Deutlicher · 400 kcal']].map(([v,l])=>`<option value="${v}" ${v===d.change?'selected':''}>${l}</option>`).join('')}</select></div><p class="small muted">Mifflin–St.-Jeor liefert eine Schätzung. Bei Gewichtserhaltung verwenden wir keinen Zuschlag.</p>`:'';
 const targets=step===2?`<h2>Deine Tagesziele</h2><p class="small muted">Geschätzter Erhaltungsbedarf: ${num(estimate.maintenance,0)} kcal/Tag. Alle Ziele kannst du später ändern.</p><div class="twocolfields">${field('kcal','Kalorienziel (kcal)',d.kcal||estimate.kcal,'numeric')}${field('protein','Eiweißziel (g)',d.protein)}${field('sugar','Zucker-Richtwert (g)',d.sugar)}</div><div class="field"><label for="setup-secondaryMetric">Anzeige neben Kalorien</label><select id="setup-secondaryMetric"><option value="protein" ${d.secondaryMetric==='protein'?'selected':''}>Eiweiß</option><option value="sugar" ${d.secondaryMetric==='sugar'?'selected':''}>Zucker</option></select></div><p class="small muted">90 g Gesamtzucker ist die EU-Kennzeichnungsreferenz für Erwachsene – kein Mindestziel. Du kannst den Richtwert anpassen.</p>`:'';
 return `<div class="onboarding-page"><div class="onboarding-panel"><div class="eyebrow">Weight App · Einrichtung</div><h1>Dein persönlicher Start</h1><div class="small muted">Schritt ${step+1} von 3</div><div class="onboarding-progress"><span style="width:${(step+1)*100/3}%"></span></div>${goal}${profile}${targets}<div class="btnrow setup-controls">${step?'<button class="btn secondary" data-action="setupback">Zurück</button>':''}<button class="btn" data-action="setupnext">${step===2?'App starten':'Weiter'}</button></div>${step===0?'<button class="btn secondary full" data-action="setupimport">Vorhandenes JSON-Backup importieren</button>':''}</div></div>`;
}
async function setupAdvance(){const d=setupCapture();if(onboardingStep===0){if(!(n(d.start)>0&&n(d.start)<500&&n(d.target)>0&&n(d.target)<500))return toast('Bitte zwei gültige Gewichte eingeben.');}
 if(onboardingStep===1){if(!(n(d.age)>=18&&n(d.age)<=120&&n(d.height)>=100&&n(d.height)<=240))return toast('Bitte gültiges Alter und Größe eingeben.');}
 if(onboardingStep<2){onboardingStep++;return render()}
 if(!(n(d.kcal)>=800&&n(d.kcal)<=9000&&n(d.protein)>0&&n(d.sugar)>0))return toast('Bitte gültige Ernährungsziele eingeben.');
 const estimate=onboardingEstimate();S.settings={...S.settings,startWeight:n(d.start),targetWeight:n(d.target),kcalGoal:n(d.kcal),proteinGoal:n(d.protein),sugarGoal:n(d.sugar),secondaryMetric:d.secondaryMetric,maintenanceKcal:estimate.maintenance,maintenanceHistory:[{date:today(),value:estimate.maintenance}],calcProfile:{sex:d.sex,age:d.age,height:d.height,weight:d.start,activity:d.activity,change:d.change}};
 S.phases=[{id:'first',start:n(d.start),target:n(d.target),started:today(),reached:null}];S.meta.setupComplete=true;await persist();try{localStorage.removeItem('weight-app-setup-draft-v1')}catch(e){}tab='today';render();toast('Einrichtung abgeschlossen. Willkommen!');
}
function settingsView(){return `<header class="top"><div><div class="eyebrow">Deine App</div><h1>Einstellungen</h1></div><button type="button" data-action="settingsback" aria-label="Einstellungen schließen" title="Zurück zur vorherigen Seite">×</button></header><main class="content"><section class="card"><h2>Ziele</h2><p class="small muted">Modus: <strong>${goalDirection()===0?'Gewicht halten':goalDirection()>0?'Gewichtszunahme':'Gewichtsabnahme'}</strong> · wird anhand deines Gewichtsziels automatisch bestimmt.</p><form id="settingsform"><div class="twocolfields"><div class="field"><label for="startWeight">Startgewicht (kg)</label><input id="startWeight" inputmode="decimal" value="${num(S.settings.startWeight)}" required></div><div class="field"><label for="targetWeight">Zielgewicht (kg)</label><input id="targetWeight" inputmode="decimal" value="${num(S.settings.targetWeight)}" required></div><div class="field"><label for="kcalGoal">Kalorienziel (kcal)</label><input id="kcalGoal" inputmode="numeric" value="${S.settings.kcalGoal}" required></div><div class="field"><label for="proteinGoal">Eiweißziel (g)</label><input id="proteinGoal" inputmode="decimal" value="${num(S.settings.proteinGoal)}" required></div><div class="field"><label for="sugarGoal">Zucker-Richtwert (g/Tag)</label><input id="sugarGoal" inputmode="decimal" value="${num(S.settings.sugarGoal||90)}" required></div></div><div class="field"><label for="secondaryMetric">Zusätzlicher Nährwert neben Kalorien</label><select id="secondaryMetric"><option value="protein" ${secondaryMetric()==='protein'?'selected':''}>Eiweiß</option><option value="sugar" ${secondaryMetric()==='sugar'?'selected':''}>Zucker</option></select></div><p class="small muted">90 g Gesamtzucker sind eine allgemeine EU-Kennzeichnungsreferenz, kein Mindestziel. Der Richtwert ist individuell anpassbar.</p><button class="btn full" type="submit">Änderungen speichern</button></form><div class="maintenance-card"><div class="statlabel">Geschätzter Erhaltungsbedarf</div><div class="statnum">${S.settings.maintenanceKcal>0?num(S.settings.maintenanceKcal,0)+' kcal/Tag':'Noch nicht berechnet'}</div><p class="footnote">${S.settings.maintenanceKcal>0?'Grundlage deiner Energiebilanz. Das Kalorienziel inklusive Zu- oder Abschlag bleibt separat gespeichert.':'Für die Energiebilanz auf der Ernährungsseite bitte zunächst den Rechner verwenden.'}</p></div><button class="btn secondary full calculator-entry" type="button" data-action="caloriecalc">Kalorienempfehlung berechnen →</button><p class="footnote">Zieländerungen verändern nicht deine gespeicherten Einträge. Für eine neue Zielphase bei erreichtem Gewicht nutze den Fortschritt-Screen.</p></section><section class="card"><h2>Lebensmittel & Gerichte</h2><p class="small muted">Lebensmittel, Gerichte und Getränke gemeinsam verwalten. Frühere Tagebucheinträge bleiben unverändert.</p><button class="btn secondary full" type="button" data-action="managefoods">Lebensmittel & Gerichte verwalten</button></section><section class="card"><h2>Deine Daten</h2><p class="small muted">Alle Einträge bleiben lokal auf diesem Gerät und in diesem Browser gespeichert. Die App nutzt keine Anmeldung und keinen eigenen Server für persönliche Daten.</p><div class="btnrow">${htmlButton('JSON importieren','import','secondary')}${htmlButton('JSON exportieren','export','secondary')}</div><p class="footnote">Beim Import werden alle vorhandenen Daten vollständig ersetzt, nicht zusammengeführt.</p><div class="hr"></div><div class="delete-action">${htmlButton('Alle Daten löschen','clear','secondary danger sm')}</div></section><section class="card"><h2>Darstellung & Installation</h2><p class="small muted">Hell/Dunkel folgt deinen Geräteeinstellungen. Auf Samsung kannst du die veröffentlichte HTTPS-Seite im Browser zum Startbildschirm hinzufügen bzw. installieren.</p><p class="footnote">Die installierte App ist nach dem ersten Laden offline nutzbar. Barcode-Produktabfragen benötigen eine Internetverbindung, sofern das Produkt noch nicht lokal gespeichert ist.</p></section></main>`}
function bottomNav(){return `<nav class="bottom" aria-label="Hauptnavigation">${[['today','home','Heute'],['nutrition','nutrition','Ernährung'],['progress','progress','Fortschritt'],['training','training','Training']].map(([t,i,l])=>`<button class="navbtn ${tab===t?'active':''}" data-action="go:${t}"><span class="symbol">${appIcon(i,23)}</span>${l}</button>`).join('')}</nav>`}
function render(){let priorSheet=document.querySelector('.sheet');let oldScroll=priorSheet?.scrollTop??0;let oldSheet=priorSheet?.dataset.sheet;let views={today:todayView,nutrition:nutritionView,progress:progressView,training:trainingView,trainingsession:trainingSessionView,traininglibrary:trainingLibraryView,trainingtimer:trainingTimerView,settings:settingsView};$('#app').innerHTML=(!S.meta?.setupComplete?onboardingView():(views[tab]||todayView)()+bottomNav())+(sheet?renderSheet():'')+photoOverlay();bind();let newSheet=document.querySelector('.sheet');if(newSheet&&oldSheet===sheet)newSheet.scrollTop=oldScroll;else if(newSheet&&sheet==='meal'){restoreMealPosition(newSheet)}if(sheet==='scan')startCamera()}
// Preserve the exact visible result rather than only the pixel scroll offset.
function rememberMealPosition(){const sh=document.querySelector('.sheet');if(!sh||sheet!=='meal')return;mealScrollPosition=sh.scrollTop;const nodes=[...sh.querySelectorAll('#foodresults [data-action^="choosefood:"],#reciperesults [data-action^="selectrecipe:"]')];const top=sh.getBoundingClientRect().top+70;const hit=nodes.find(n=>n.getBoundingClientRect().bottom>top);mealScrollAnchor=hit?{action:hit.dataset.action,offset:hit.getBoundingClientRect().top-sh.getBoundingClientRect().top}:null}
function restoreMealPosition(sh){sh.scrollTop=mealScrollPosition;if(!mealScrollAnchor)return;const hit=[...sh.querySelectorAll('[data-action]')].find(n=>n.dataset.action===mealScrollAnchor.action);if(hit){const delta=hit.getBoundingClientRect().top-sh.getBoundingClientRect().top-mealScrollAnchor.offset;sh.scrollTop+=delta}}
function mealPairSuggestions(){if(!builder.length||mealMode!=='food'||mealSearchDraft.trim())return '';const ids=new Set(builder.map(x=>x.foodId));let counts=new Map();for(const meal of S.meals){const distinct=new Set((meal.items||[]).map(x=>x.foodId).filter(Boolean));if(![...ids].some(id=>distinct.has(id)))continue;for(const id of distinct){if(ids.has(id))continue;counts.set(id,(counts.get(id)||0)+1)}}const suggestions=[...counts].filter(([id,c])=>c>=2&&S.foods.some(f=>f.id===id&&f.kind==='food')).sort((a,b)=>b[1]-a[1]).slice(0,3);if(!suggestions.length)return '';return `<div class="meal-suggestions"><div class="small muted">Oft dazu erfasst</div><div class="chiprow">${suggestions.map(([id])=>{const f=find(S.foods,id);return `<button type="button" class="chip" data-action="choosefood:${esc(id)}">＋ ${esc(cleanToast(f.name))}</button>`}).join('')}</div></div>`}
function mealReviewSheet(){let t=mealTotals({items:builder});return wrapSheet('Mahlzeit prüfen',`<form id="mealform"><div class="meal-review-top"><div class="statlabel">${builder.length} ${builder.length===1?'Lebensmittel':'Lebensmittel'}</div><div class="statnum">${num(t.kcal,0)} kcal <span class="small muted">· ${num(t[secondaryMetric()]||0,1)} g ${metricLabel()}</span></div></div><div class="meal-review-items">${builder.map((v,i)=>{let f=v.snapshot||find(S.foods,v.foodId),x=foodTotals(f||{kcal:0,protein:0},v.amount);return `<div class="entry"><div class="grow"><strong>${esc(cleanToast(f?.name||'Lebensmittel'))}</strong><div class="meta">${num(v.amount)} g · ${num(x.kcal,0)} kcal · ${num(x[secondaryMetric()]||0,1)} g ${metricLabel()}</div></div><button type="button" class="btn sm secondary" data-action="removeingredient:${i}" aria-label="${esc(f?.name||'Lebensmittel')} entfernen">Entfernen</button></div>`}).join('')}</div><button class="btn secondary full" type="button" data-action="reviewback">＋ Weitere Lebensmittel hinzufügen</button><div class="field"><label for="mealdate">Datum</label><input id="mealdate" type="date" value="${mealDateDraft||date}" required></div><div class="field"><label for="mealcat">Kategorie</label><select id="mealcat">${['Frühstück','Mittagessen','Abendessen','Snack'].map(c=>`<option ${mealCat===c?'selected':''}>${c}</option>`).join('')}</select></div><button type="submit" class="btn full" ${!builder.length?'disabled':''}>Mahlzeit eintragen</button><button type="button" class="btn text-action full" data-action="saverecipe" ${!builder.length?'disabled':''}>Als Gericht speichern</button></form>`)}
function wrapSheet(title,content){return `<div class="sheetbg" id="backdrop"><div class="sheet" data-sheet="${sheet}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="sheethead"><h2>${esc(title)}</h2><button data-action="close" aria-label="Schließen">×</button></div>${content}</div></div>`}
const cleanToast=s=>String(s??'').replace(/\s*\(Sammy\)/gi,'');const barcodeIcon=appIcon('barcode',21);const scanButton=()=>`<button class="iconbtn" type="button" data-action="scan" aria-label="Barcode scannen" title="Barcode scannen">${barcodeIcon}</button>`;
function foodMoreButton(f){return `<button type="button" class="food-more" data-action="foodmenu:${esc(f.id)}" aria-label="${esc(f.name)} verwalten" title="Bearbeiten oder entfernen">⋮</button>`}
function foodMenuMarkup(f){return foodMenuId===f.id?`<div class="food-actions"><button type="button" class="btn sm secondary" data-action="foodedit:${esc(f.id)}">${appIcon('check',14)} Bearbeiten</button><button type="button" class="btn sm secondary danger" data-action="foodremove:${esc(f.id)}">Entfernen</button></div>`:''}
function manageFoodList(){const q=foodManageSearch.toLocaleLowerCase('de-DE'),entries=[...S.foods.filter(f=>(foodManageKind==='all'||foodManageKind===f.kind)&&f.name.toLocaleLowerCase('de-DE').includes(q)).map(data=>({type:'food',data})),...S.recipes.filter(r=>(foodManageKind==='all'||foodManageKind==='recipe')&&r.name.toLocaleLowerCase('de-DE').includes(q)).map(data=>({type:'recipe',data}))].sort((a,b)=>a.data.name.localeCompare(b.data.name,'de'));return entries.map(({type,data:e})=>{const t=type==='recipe'?mealTotals({items:e.items}):e;return `<div class="managed-food"><div class="foodresult"><div class="foodicon">${esc(type==='recipe'?recipeIcon(e):e.icon||'🍽️')}</div><div class="grow"><div class="foodname">${esc(cleanToast(e.name))}</div><div class="foodmeta">${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0,1)} g ${metricLabel()} ${type==='recipe'?'pro Portion · Gericht':'/ 100 '+(e.kind==='drink'?'ml':'g')}</div></div><button type="button" class="food-more" data-action="${type==='recipe'?'recipemenu':'foodmenu'}:${esc(e.id)}" aria-label="${esc(e.name)} verwalten">⋮</button></div>${foodMenuId===e.id?`<div class="food-actions"><button type="button" class="btn sm secondary" data-action="${type==='recipe'?'recipeedit':'foodedit'}:${esc(e.id)}">Bearbeiten</button><button type="button" class="btn sm secondary danger" data-action="${type==='recipe'?'reciperemove':'foodremove'}:${esc(e.id)}">Entfernen</button></div>`:''}</div>`}).join('')||'<p class="small muted">Keine passenden Einträge vorhanden.</p>'}
function manageFoodsSheet(){return wrapSheet('Lebensmittel & Gerichte verwalten',`<div class="field"><label>Gespeicherte Einträge durchsuchen</label><input id="managefoodquery" autocomplete="off" value="${esc(foodManageSearch)}" placeholder="Name suchen …"></div><div class="catalog-filters food-manage-tabs">${[['all','Alle'],['food','Lebensmittel'],['recipe','Gerichte'],['drink','Getränke']].map(([k,l])=>`<button type="button" class="chip ${foodManageKind===k?'sel':''}" data-action="foodfilter:${k}">${l}</button>`).join('')}</div><div id="managedfoodresults">${manageFoodList()}</div><button class="btn secondary full" data-action="newentry" style="margin-top:12px">＋ Neuen Eintrag erstellen</button><p class="footnote">Änderungen gelten für zukünftige Einträge. Bereits erfasste Mahlzeiten bleiben unverändert.</p>`)}
function foodSearch(kind){let q=$('#foodquery')?.value??(sheet==='meal'?mealSearchDraft:drinkSearchDraft);let a=sortEntries(S.foods.filter(f=>f.kind===kind&&f.name.toLocaleLowerCase('de-DE').includes(q.toLocaleLowerCase('de-DE'))),kind==='drink'?drinkSort:foodSort);return a.slice(0,25).map(f=>`<div class="food-result-wrap"><div class="foodresult ${kind==='drink'&&selectedDrink?.id===f.id?'is-selected':''}" data-action="choosefood:${f.id}" role="button" tabindex="0"><div class="foodicon">${esc(f.icon||'🍽️')}</div><div class="grow"><div class="foodname">${esc(cleanToast(f.name))}</div><div class="foodmeta">${num(f.kcal)} kcal · ${num(secondaryMetric()==='sugar'?(sugarBase(f)??0):f.protein)} g ${metricLabel()} / 100 ${kind==='drink'?'ml':'g'}</div></div><span class="muted">${kind==='drink'&&selectedDrink?.id===f.id?'✓':'＋'}</span></div>${foodMoreButton(f)}${foodMenuMarkup(f)}</div>`).join('')||'<p class="muted small">Keine passenden Lebensmittel gefunden.</p>'}

function recipeIsDirect(r){return Boolean(r?.note?.includes('Direkt eingegebene')||r?.directNutrition)}
function recipeKnownWeight(r){if(!r)return null;if(r.portionWeightKnown===false)return null;if(r.portionWeightKnown===true)return Number(r.portionWeight)||null;if(r?.note?.includes('ohne Zutatenliste'))return r.note.includes('pro 100 g')?100:(r.items?.[0]?.amount!==100?r.items?.[0]?.amount:null);return r.items?.length?r.items.reduce((total,i)=>total+Number(i.amount||0),0):null}
function catalogList(){const q=mealSearchDraft.trim().toLocaleLowerCase('de-DE');let entries=[...S.foods.filter(f=>f.kind==='food'&&catalogFilter!=='recipe').map(f=>({kind:'food',data:f})),...S.recipes.filter(r=>catalogFilter!=='food').map(r=>({kind:'recipe',data:r}))].filter(e=>e.data.name.toLocaleLowerCase('de-DE').includes(q));entries.sort((a,b)=>foodSort==='alpha'?a.data.name.localeCompare(b.data.name,'de'):foodSort==='frequent'?(b.data.used||0)-(a.data.used||0)||a.data.name.localeCompare(b.data.name,'de'):(b.data.lastUsed||'').localeCompare(a.data.lastUsed||'')||(b.data.used||0)-(a.data.used||0)||a.data.name.localeCompare(b.data.name,'de'));return entries.slice(0,60).map(({kind,data:e})=>{const t=kind==='recipe'?mealTotals({items:e.items}):{kcal:e.kcal,protein:e.protein,sugar:sugarBase(e)};return `<div class="food-result-wrap"><div class="foodresult" data-action="${kind==='recipe'?'selectrecipe':'choosefood'}:${esc(e.id)}" role="button" tabindex="0"><div class="foodicon">${esc(kind==='recipe'?recipeIcon(e):e.icon||'🍽️')}</div><div class="grow"><div class="foodname">${esc(cleanToast(e.name))}</div><div class="foodmeta">${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0,1)} g ${metricLabel()} ${kind==='recipe'?'pro Portion':'/ 100 g'} · ${kind==='recipe'?'Gericht':'Lebensmittel'}</div></div><span class="muted">＋</span></div>${kind==='food'?foodMoreButton(e)+foodMenuMarkup(e):''}</div>`}).join('')||'<p class="small muted">Keine passenden Einträge gefunden.</p>'}
function recipeIcon(r){if(r?.icon)return r.icon;return r?.name?.match(/brot|toast/i)?'🥪':r?.name?.match(/müsli|joghurt|smacks|choco|tresor/i)?'🥣':'🥘'}
function recipeList(){let q=recipeFilter.toLocaleLowerCase('de-DE').trim();let matching=sortEntries(S.recipes.filter(r=>r.name.toLocaleLowerCase('de-DE').includes(q)),recipeSort);let paginated=matching.slice(0,(recipePage+1)*12);return `${paginated.map(r=>{let t=mealTotals({items:r.items});return `<div class="foodresult" data-action="selectrecipe:${r.id}" role="button" tabindex="0"><div class="foodicon">${esc(recipeIcon(r))}</div><div class="grow"><div class="foodname">${esc(cleanToast(r.name))}</div><div class="foodmeta">${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0)} g ${metricLabel()}${r.quality==='berechnet'?' · geschätzt':''}</div></div><span class="muted">＋</span></div>`}).join('')||'<p class="muted small">Keine passenden Gerichte gefunden.</p>'}${matching.length>paginated.length?`<button type="button" class="btn sm secondary full" data-action="morerecipes">Weitere Gerichte anzeigen (${matching.length-paginated.length})</button>`:''}`}

function mealSheet(){let m=mealEditId?find(S.meals,mealEditId):null,t=mealTotals({items:builder});return wrapSheet(m?'Mahlzeit bearbeiten':'Mahlzeit hinzufügen',`${builder.length?`<div class="meal-compact"><div class="meal-compact-summary"><div><strong>Aktuelle Mahlzeit</strong><div class="small muted">${builder.length} Einträge · ${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0,1)} g ${metricLabel()}</div></div><button type="button" class="btn sm" data-action="reviewmeal">Prüfen ›</button></div></div>`:''}<div class="meal-picker"><div class="section-title">Hinzufügen</div><div class="field"><label>Lebensmittel oder Gericht suchen</label><div class="searchrow"><input id="foodquery" placeholder="Lebensmittel oder Gericht suchen …" autocomplete="off" value="${esc(mealSearchDraft)}">${scanButton()}</div></div><div class="catalog-filters">${[['all','Alle'],['food','Lebensmittel'],['recipe','Gerichte']].map(([k,l])=>`<button class="chip ${catalogFilter===k?'sel':''}" data-action="catalogfilter:${k}">${l}</button>`).join('')}</div>${mealPairSuggestions()}${sortChoices('food',foodSort)}<div id="foodresults">${catalogList()}</div><button type="button" class="btn secondary full" data-action="newentry">＋ Neuen Eintrag erstellen</button></div>`)}
function quantitySheet(){if(selectedRecipe){let t=mealTotals({items:selectedRecipe.items}),weight=recipeKnownWeight(selectedRecipe),grams=recipeQuantityMode==='gram'&&weight,amount=n(recipeQuantityDraft)||1,factor=grams?amount/weight:amount;return wrapSheet('Menge auswählen',`<div class="foodresult"><div class="foodicon">${esc(recipeIcon(selectedRecipe))}</div><div><strong>${esc(selectedRecipe.name)}</strong><div class="foodmeta">${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0,1)} g ${metricLabel()} je Portion</div></div></div><form id="recipequantityform">${weight?`<div class="segment"><button type="button" class="${!grams?'sel':''}" data-action="recipeunit:portion">Portion / Stück</button><button type="button" class="${grams?'sel':''}" data-action="recipeunit:gram">Gramm</button></div>`:''}<div class="field"><label>${grams?'Menge (g)':'Anzahl Portionen'}</label><div class="quantity-stepper"><button type="button" data-action="recipestep:-1">−</button><input id="recipequantity" inputmode="decimal" required value="${esc(recipeQuantityDraft)}"><button type="button" data-action="recipestep:1">＋</button></div></div><div class="hint" id="recipequantitypreview">${num(t.kcal*factor,0)} kcal · ${num((t[secondaryMetric()]||0)*factor,1)} g ${metricLabel()}</div><button class="btn full" type="submit">Zur Mahlzeit hinzufügen</button></form>`)}let f=selectedFood,ps=f.portions||[],isDrink=f.kind==='drink',usePortion=!isDrink&&ps.length&&quantityMode==='portion',cur=ps[quantityPortion]||ps[0];return wrapSheet('Menge auswählen',`<div class="foodresult"><div class="foodicon">${esc(f.icon||'🍽️')}</div><div><strong>${esc(cleanToast(f.name))}</strong><div class="foodmeta">${num(f.kcal)} kcal · ${num(secondaryMetric()==='sugar'?(sugarBase(f)??0):f.protein)} g ${metricLabel()} / 100 ${isDrink?'ml':'g'}</div></div></div><form id="quantityform">${!isDrink&&ps.length?`<div class="field"><label>Einheit auswählen</label><div class="segment"><button type="button" class="${!usePortion?'sel':''}" data-action="unit:gram">Gramm</button><button type="button" class="${usePortion?'sel':''}" data-action="unit:portion">Portion / Stück</button></div></div>`:''}${usePortion?`<div class="field"><label>Portionsgröße</label><select id="portionsize">${ps.map((v,i)=>`<option value="${i}" ${i===quantityPortion?'selected':''}>${esc(v.name)} (${num(v.amount)} g)</option>`).join('')}</select></div><div class="field"><label>Anzahl ${esc(cur.name)}</label><div class="quantity-stepper"><button type="button" data-action="quantitystep:-0.5" aria-label="Halbe Portion weniger">−</button><input id="quantity" inputmode="decimal" value="1" required aria-label="Anzahl der Portionen"><button type="button" data-action="quantitystep:0.5" aria-label="Halbe Portion mehr">＋</button></div></div>`:`<div class="field"><label>Menge (${isDrink?'ml':'g'})</label><input id="quantity" inputmode="decimal" value="${f.lastAmount||(isDrink?250:100)}" required></div><div class="chiprow">${(isDrink?[150,200,250,330,500]:[50,100,150,200]).map(x=>`<button type="button" class="chip ${x===(f.lastAmount||(isDrink?250:100))?'sel':''}" data-action="quantity:${x}">${num(x)} ${isDrink?'ml':'g'}</button>`).join('')}</div>`}<div class="hint" id="quantitypreview" style="margin:15px 0"></div><button class="btn full" type="submit">${isDrink?'Getränk speichern':'Zur Mahlzeit hinzufügen'}</button></form>`)}

function foodSheet(){let f=editId?find(S.foods,editId):null,kind=f?.kind||(currentBarcodeContext==='drink'?'drink':'food');return wrapSheet(f?'Lebensmittel bearbeiten':'Neues Lebensmittel',`<form id="foodform"><div class="segment"><button type="button" class="${kind==='food'?'sel':''}" data-action="foodkind:food">Lebensmittel</button><button type="button" class="${kind==='drink'?'sel':''}" data-action="foodkind:drink">Getränk</button></div><input id="foodkind" type="hidden" value="${kind}"><div class="searchrow" style="margin-bottom:16px"><select id="foodicon" style="max-width:66px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--text);font-size:22px" aria-label="Symbol auswählen">${[...new Set([...FOOD_ICON_CHOICES,...(f?.icon?[f.icon]:[])])].map(i=>`<option ${i===(f?.icon||(kind==='drink'?'🥛':'🍽️'))?'selected':''}>${i}</option>`).join('')}</select><input id="foodname" class="searchinput" placeholder="Name" value="${esc(f?.name||'')}" required>${scanButton()}</div><div class="twocolfields"><div class="field"><label>kcal / 100 <span class="unit">${kind==='drink'?'ml':'g'}</span></label><input id="foodkcal" inputmode="decimal" value="${f?num(f.kcal):''}" required></div><div class="field"><label>Eiweiß / 100 <span class="unit">${kind==='drink'?'ml':'g'}</span></label><input id="foodprotein" inputmode="decimal" value="${f?num(f.protein):''}" required></div><div class="field"><label>Zucker / 100 <span class="unit">${kind==='drink'?'ml':'g'}</span></label><input id="foodsugar" inputmode="decimal" value="${f?.sugar==null?'':num(f.sugar,2)}" placeholder="Falls bekannt"></div></div><div class="field"><label>Barcode (EAN/GTIN) <span class="muted small">optional</span></label><input id="foodbarcode" inputmode="numeric" pattern="[0-9]*" placeholder="z. B. 4001234567890" value="${esc(f?.barcode||'')}"></div><div class="field"><label>Eigene Portionsgrößen <span class="muted small">(optional)</span></label><div id="portionfields">${(f?.portions||[]).map(p=>portionFields(p.name,p.amount)).join('')}</div><button type="button" class="btn secondary sm" data-action="addportion">＋ Portion hinzufügen</button></div><div id="scannedmsg" class="hint" style="display:none;margin-bottom:13px"></div><button type="submit" class="btn full">${f?'Änderungen speichern':'Lebensmittel speichern'}</button></form>`)}
function portionFields(name='',amount=''){return `<div class="searchrow" style="margin:6px 0"><input class="searchinput portionname" placeholder="z. B. Scheibe" value="${esc(name)}"><input class="searchinput portionamount" placeholder="z. B. 50 g" inputmode="decimal" value="${esc(amount)}"><button type="button" class="iconbtn" data-action="delportion">×</button></div>`}
function drinkSheet(){let d=editId?find(S.drinks,editId):null;let chosen=d?(d.snapshot||find(S.foods,d.foodId)):selectedDrink;return wrapSheet(d?'Getränk bearbeiten':'Getränk hinzufügen',`${chosen?`<div class="meal-draft drink-draft"><h2 class="section-title">Aktuelles Getränk</h2><strong>${esc(chosen.name)}</strong><form id="drinkform"><div class="field" style="margin-top:13px"><label>Menge (ml)</label><input id="drinkamount" inputmode="decimal" value="${d?.amount||chosen.lastAmount||250}" required></div><div class="chiprow">${[150,200,250,330,500].map(q=>`<button type="button" class="chip ${q===(d?.amount||chosen.lastAmount||250)?'sel':''}" data-action="drinkamount:${q}">${q} ml</button>`).join('')}</div><div class="hint" id="drinkpreview" style="margin:15px 0"></div><div class="field"><label>Datum</label><input type="date" id="drinkdate" value="${d?.date||date}" required></div><button class="btn full" type="submit">Getränk speichern</button></form></div>`:''}<div class="meal-picker"><div class="section-title">Hinzufügen</div><div class="field"><label>Getränk suchen</label><div class="searchrow"><input id="foodquery" placeholder="Getränk suchen …" autocomplete="off" value="${esc(drinkSearchDraft)}">${scanButton()}</div></div>${sortChoices('drink',drinkSort)}<div id="foodresults">${foodSearch('drink')}</div><button type="button" class="btn secondary full" data-action="newfood:drink">＋ Neues Getränk</button></div>`)}

function weightSheet(){let w=editId?find(S.weights,editId):null;return wrapSheet(w?'Gewicht bearbeiten':'Gewicht eintragen',`<form id="weightform"><div class="field"><label>Datum</label><input id="weightdate" type="date" value="${w?.date||today()}" required></div><div class="field"><label>Gewicht (kg)</label><input id="weightvalue" inputmode="decimal" value="${w?num(w.value):num(actualWeight())}" required autofocus></div><p class="hint">Ein Gewicht pro Tag: Ein erneuter Eintrag für dasselbe Datum ersetzt den bisherigen Wert.</p><button class="btn full" type="submit">Gewicht speichern</button></form>`)}
function measureSheet(){let m=editId?find(S.measurements,editId):null,prev=ordered(S.measurements)[0];return wrapSheet(m?'Körpermaße bearbeiten':'Körpermaße erfassen',`<form id="measureform"><div class="field"><label>Datum</label><input id="measuredate" type="date" value="${m?.date||today()}" required></div>${[['waist','Taille'],['chest','Brust'],['arm','Oberarm']].map(([key,label])=>`<div class="field"><label>${label} (cm) <span class="muted small">optional</span></label><input id="measure-${key}" inputmode="decimal" value="${m?.[key]!=null?num(m[key]):prev?.[key]!=null?num(prev[key]):''}" placeholder="–"></div>`).join('')}<p class="hint">Mindestens einen Wert angeben. Je Körpermaß und Datum gibt es nur einen Wert.</p><button class="btn full" type="submit">Messung speichern</button></form>`)}
function trainingSheet(){let tr=editId?find(S.trainings,editId):null,areas=tr?.areas||[];let selected=tr?.exercises||(!editId?chosenExercises():[]);const suggestedDuration=activeTraining?(elapsedTraining()<900?'Unter 15':elapsedTraining()<1800?'15–30':'30–45'):'30–45';return wrapSheet(tr?'Training bearbeiten':activeTraining?'Training abschließen':'Training eintragen',`<form id="trainingform"><div class="field"><label>Datum</label><input type="date" id="trainingdate" value="${tr?.date||today()}" required></div><div class="field"><label>Trainingsdauer</label>${[['Unter 15','Unter 15 Minuten'],['15–30','15–30 Minuten'],['30–45','30–45 Minuten']].map((a,i)=>`<label class="radio"><input type="radio" name="duration" value="${a[0]}" ${(tr?.duration||suggestedDuration)===a[0]?'checked':''}>${a[1]}</label>`).join('')}</div><div class="field"><label>Trainierte Bereiche</label><div class="checkgrid">${['Ganzkörper','Oberkörper','Arme','Brust','Rücken','Beine','Rumpf','Mobilität'].map(a=>`<label><input type="checkbox" name="area" value="${a}" ${areas.includes(a)?'checked':''}>${a}</label>`).join('')}</div></div><div class="field"><label>Trainierte Übungen <span class="muted small">(optional)</span></label><div class="checkgrid">${EXERCISES.filter(e=>selected.includes(e.id)).map(e=>`<label><input type="checkbox" name="trainingexercise" value="${e.id}" checked>${esc(e.name)}</label>`).join('')||'<p class="small muted">Keine Übungen markiert.</p>'}</div></div><div class="field"><label>Trainingsnotiz <span class="muted small">(optional)</span></label><textarea id="trainingnote" placeholder="Übungen, Hanteln, Besonderheiten …">${esc(tr?.note||'')}</textarea></div><button class="btn full" type="submit">Training speichern</button></form>`)}
function scanSheet(){return wrapSheet('Barcode scannen',`<div class="camera" id="camera"><div><div style="font-size:46px">▥</div><div class="small">Kamera wird vorbereitet …</div></div></div><p class="small muted">Barcode innerhalb des Rahmens platzieren. Falls die Kamera nicht verfügbar ist, kannst du die EAN/GTIN manuell eingeben.</p><form id="scanform"><div class="field"><label>Barcode manuell eingeben</label><input id="barcodefield" inputmode="numeric" autocomplete="off" placeholder="EAN / GTIN" pattern="[0-9]{8,14}" required></div><button type="submit" class="btn full">Produkt suchen</button></form><p class="footnote" id="scanstatus">Der Barcode wird zuerst in deinen lokalen Lebensmitteln und sonst über Open Food Facts gesucht. Die Online-Abfrage benötigt Internet.</p><button class="btn secondary full" style="margin-top:12px" data-action="scanback">Zurück</button>`)}
function recipeSheet(){return wrapSheet('Gericht speichern',`<form id="recipeform"><div class="field"><label>Name des Gerichts</label><input id="recipename" required placeholder="z. B. Brot mit Käse"></div><div class="field"><label>Symbol</label><select id="newrecipeicon">${FOOD_ICON_CHOICES.map(i=>`<option ${i==='🥘'?'selected':''}>${i}</option>`).join('')}</select></div><div class="hint">Alle aktuell ausgewählten Bestandteile werden als Vorlage gespeichert und können später wieder hinzugefügt werden.</div><button class="btn full" style="margin-top:15px" type="submit">Gericht speichern</button></form>`)}
function directRecipeSheet(editing=false){const r=editing?recipeEditSnapshot():null,old=r?.items?.[0]?.snapshot,per100=r?.note?.includes('pro 100 g'),known=editing?recipeKnownWeight(r):null,base=editing?(per100?100:(known||100)):100,k=editing?(per100?old?.kcal||0:foodTotals(old,r.items[0].amount).kcal):'',protein=editing?(per100?old?.protein||0:foodTotals(old,r.items[0].amount).protein):'';return wrapSheet(editing?'Gericht bearbeiten':'Nährwerte eingeben',`<form id="directrecipeform"><div class="field"><label>Name</label><input id="directrecipename" value="${esc(r?.name||'')}" required placeholder="z. B. Pasta mit Gemüse"></div><div class="segment"><button type="button" class="${!per100?'sel':''}" data-action="directmode:portion">Pro Portion</button><button type="button" class="${per100?'sel':''}" data-action="directmode:hundred">Pro 100 g</button></div><input type="hidden" id="directmode" value="${per100?'hundred':'portion'}"><div class="twocolfields"><div class="field"><label id="directkcallabel">kcal ${per100?'pro 100 g':'pro Portion'}</label><input id="directkcal" value="${k!==''?num(k,2):''}" inputmode="decimal" required></div><div class="field"><label id="directproteinlabel">Eiweiß (g) ${per100?'pro 100 g':'pro Portion'}</label><input id="directprotein" value="${protein!==''?num(protein,2):''}" inputmode="decimal" required></div><div class="field"><label>Zucker (g) ${per100?'pro 100 g':'pro Portion'}</label><input id="directsugar" value="${old?.sugar==null?'':num(per100?old.sugar:foodTotals(old,r.items[0].amount).sugar,2)}" inputmode="decimal" placeholder="Falls bekannt"></div></div><div class="field" id="directweightfield" ${per100?'hidden':''}><label>Portionsgewicht (g) <span class="small muted">optional</span></label><input id="directweight" value="${known&&(!per100)?num(known,2):''}" inputmode="decimal" placeholder="Falls bekannt"></div><p class="footnote" id="directhint">${per100?'Werte pro 100 g.':'Ohne bekanntes Gewicht sind nur Portionen auswählbar.'}</p><div class="field"><label>Symbol</label><select id="directicon">${[...new Set([...FOOD_ICON_CHOICES,recipeIcon(r)])].map(i=>`<option ${i===recipeIcon(r)?'selected':''}>${i}</option>`).join('')}</select></div><button class="btn full" type="submit">${editing?'Änderungen speichern':'Eintrag speichern'}</button></form>`)}
function saveDirectRecipe(){
 const name=$('#directrecipename').value.trim(),ks=$('#directkcal').value.trim(),ps=$('#directprotein').value.trim(),ss=$('#directsugar')?.value.trim()||'',sugar=ss===''?null:n(ss),k=n(ks),prot=n(ps),mode=$('#directmode').value;
 if((ss!==''&&(!Number.isFinite(Number(ss.replace(',','.')))||sugar<0||sugar>1000)))return toast('Bitte gültigen Zuckerwert eingeben.');if(!name||!ks||!ps||![ks,ps].every(v=>Number.isFinite(Number(v.replace(',','.'))))||k<0||prot<0||k>20000||prot>1000)return toast('Bitte Name und gültige Nährwerte eingeben.');
 const wt=$('#directweight')?.value.trim()||'';
 if(mode==='portion'&&wt&&(!Number.isFinite(Number(wt.replace(',','.')))||n(wt)<=0||n(wt)>50000))return toast('Bitte ein gültiges Portionsgewicht eingeben.');
 if(mode==='hundred'&&(k>1000||prot>100))return toast('Bitte plausible Werte je 100 g eingeben.');
 const amount=mode==='portion'?(wt?n(wt):100):100;
 const kcal100=mode==='portion'?k*100/amount:k,protein100=mode==='portion'?prot*100/amount:prot,sugar100=sugar===null?null:(mode==='portion'?sugar*100/amount:sugar);
 const editing=Boolean(recipeEditingId&&sheet==='recipeeditor');const id=editing?recipeEditingId:uid(),icon=$('#directicon').value;
 const snapshot={id:'recipe-food-'+id,name,kind:'food',icon,sugar:sugar100,sugarQuality:sugar===null?'unbekannt':'nutzerangabe',kcal:kcal100,protein:protein100,portions:[{name:'Portion',amount}],portionNutrition:{amount,kcal:mode==='portion'?k:k,protein:mode==='portion'?prot:prot,sugar:sugar}};
 const old=editing?find(S.recipes,id):null;const record={...old,sugar:sugar100,sugarQuality:sugar===null?'unbekannt':'nutzerangabe',id,name,icon,items:[{foodId:snapshot.id,snapshot,amount}],quality:'nutzerangabe',portionWeightKnown:mode==='hundred'||Boolean(wt),portionWeight:mode==='hundred'?100:(wt?n(wt):null),directNutrition:true,note:mode==='portion'?'Direkt eingegebene Nährwerte pro Portion (ohne Zutatenliste).':'Direkt eingegebene Nährwerte pro 100 g (ohne Zutatenliste).'};if(editing)S.recipes=S.recipes.map(x=>x.id===id?record:x);else S.recipes.push(record);
 selectedRecipe=null;recipeEditingId=null;recipeFilter='';recipePage=0;sheet=editing||catalogCreateReturn==='managefoods'?'managefoods':'meal';editId=sheet==='meal'?mealEditId:null;sync();toast(editing?'Gericht aktualisiert. Frühere Einträge bleiben unverändert.':'Eintrag gespeichert.');
}
function goalSheet(){return wrapSheet('Neues Gewichtsziel',`<form id="goalform"><div class="hint">Dein bisheriges Ziel bleibt als abgeschlossene Phase erhalten. Alle historischen Messungen bleiben unverändert.</div><div class="field" style="margin-top:15px"><label>Neues Zielgewicht (kg)</label><input id="newgoal" inputmode="decimal" value="${num(actualWeight()+4*goalDirection())}" required></div><button type="submit" class="btn full">Neue Zielphase starten</button></form>`)}
function calorieEstimate(){let w=n(wizard.weight),h=n(wizard.height),age=n(wizard.age),base=10*w+6.25*h-5*age+(wizard.sex==='male'?5:-161),maintenance=base*n(wizard.activity),change=goalDirection()*n(wizard.change);return {base,maintenance,change,goal:Math.round((maintenance+change)/25)*25,bmi:w/(h/100)**2}}
function calorieSheet(){let st=S.settings;let step=wizardStep, labels=['Deine Angaben','Bewegung im Alltag','Zieltempo','Deine Empfehlung'];let content=step===0?`<div class="field"><label>Berechnungsformel</label><div class="segment"><button type="button" class="${wizard.sex==='male'?'sel':''}" data-action="wizsex:male">Männlich</button><button type="button" class="${wizard.sex==='female'?'sel':''}" data-action="wizsex:female">Weiblich</button></div></div><div class="twocolfields"><div class="field"><label for="wage">Alter (Jahre)</label><input id="wage" inputmode="numeric" value="${esc(wizard.age)}" required></div><div class="field"><label for="wheight">Größe (cm)</label><input id="wheight" inputmode="decimal" value="${esc(wizard.height)}" required></div></div><div class="field"><label for="wweight">Aktuelles Gewicht (kg)</label><input id="wweight" inputmode="decimal" value="${esc(wizard.weight)}" required></div><p class="footnote">Die Formel benötigt Alter, Körpergröße, Gewicht und eine der beiden veröffentlichten Geschlechtsformeln. Das ist eine Schätzung, keine Stoffwechselmessung.</p>`:step===1?`<p class="small muted">Wähle die Beschreibung, die den gesamten Alltag einschließlich Training am besten trifft.</p><div class="wizard-options">${[['1.2','Überwiegend sitzend','Kaum Sport, wenig Alltagsbewegung'],['1.375','Leicht aktiv','Viel Sitzen, etwas Gehen oder Sport 1–3×/Woche'],['1.55','Mäßig aktiv','Regelmäßige Bewegung oder Sport 3–5×/Woche'],['1.725','Sehr aktiv','Körperliche Arbeit oder intensiver Sport an den meisten Tagen']].map(([v,t,d])=>`<button type="button" class="wizard-option ${wizard.activity===v?'active':''}" data-action="wizactivity:${v}"><strong>${t}</strong><span>${d}</span></button>`).join('')}</div>`:step===2?`<p class="small muted">Ziel: <strong>${goalDirection()===0?'Gewicht halten':goalDirection()>0?'Gewichtszunahme':'Gewichtsabnahme'}</strong>. Die folgenden Werte sind tägliche Auf- bzw. Abschläge zum geschätzten Erhaltungsbedarf.</p><div class="wizard-options">${[['150','Behutsam','± 150 kcal pro Tag'],['250','Moderat','± 250 kcal pro Tag'],['400','Deutlicher','± 400 kcal pro Tag']].map(([v,t,d])=>`<button type="button" class="wizard-option ${wizard.change===v?'active':''}" data-action="wizchange:${v}"><strong>${t}</strong><span>${d}</span></button>`).join('')}</div>`:(()=>{let c=calorieEstimate();return `<div class="calculator-result"><div class="muted small">Empfohlenes Kalorienziel</div><div class="calculator-number">${num(c.goal,0)} <span>kcal / Tag</span></div></div><div class="calculator-breakdown"><div class="split"><span>Geschätzter Ruheumsatz</span><strong>${num(c.base,0)} kcal</strong></div><div class="split"><span>Geschätzter Erhaltungsbedarf</span><strong>${num(c.maintenance,0)} kcal</strong></div><div class="split"><span>${goalDirection()>0?'Zuschlag':'Abschlag'} für das Ziel</span><strong>${goalDirection()>0?'+':'−'}${num(Math.abs(c.change),0)} kcal</strong></div></div>${c.bmi<18.5&&goalDirection()<0?'<div class="hint" style="margin-top:12px">Bei einem BMI unter 18,5 ist weiteres Abnehmen möglicherweise gesundheitlich problematisch. Bitte lass dich medizinisch beraten, bevor du dieses Ziel verfolgst.</div>':''}<p class="footnote">Unverbindlicher Startwert nach Mifflin–St.-Jeor und Aktivitätsfaktor. Beobachte den tatsächlichen Gewichtsverlauf über mehrere Wochen. Bestehende Einträge bleiben unangetastet.</p>`})();return wrapSheet('Kalorienempfehlung',`<div class="wizard-steps">Schritt ${step+1} von 4 · ${labels[step]}</div><div class="wizard-content">${content}</div><div class="btnrow wizard-actions">${step?`<button class="btn secondary" type="button" data-action="wizback">Zurück</button>`:''}<button class="btn" type="button" data-action="${step===3?'wizaccept':'wiznext'}">${step===3?'Empfehlung übernehmen':'Weiter'}</button></div>${step===3?'<button type="button" class="btn secondary full" data-action="wizmaintenance" style="margin-top:10px">Nur Erhaltungsbedarf speichern</button>':''}`)}
function wizardCapture(){if(wizardStep!==0)return true;let age=$('#wage'),height=$('#wheight'),weight=$('#wweight');if(age)wizard.age=age.value;if(height)wizard.height=height.value;if(weight)wizard.weight=weight.value;if(n(wizard.age)<18||n(wizard.age)>110||n(wizard.height)<110||n(wizard.height)>240||n(wizard.weight)<25||n(wizard.weight)>350){toast('Bitte plausible Angaben zu Alter, Größe und Gewicht eingeben (ab 18 Jahren).');return false}return true}
function newEntrySheet(){return wrapSheet('Neuen Eintrag erstellen',`<p class="small muted">Wähle, welche Informationen du vorliegen hast.</p><div class="new-entry-choices"><button class="new-entry-choice" data-action="entrydirect"><strong>🍽️ Nährwerte eingeben</strong><span>Lebensmittel, Getränke oder komplette Gerichte ohne bekannte Zutaten</span></button><button class="new-entry-choice" data-action="entryfood"><strong>🍎 Einzelnes Lebensmittel / Getränk</strong><span>Werte je 100 g/ml, Portionen und Barcode</span></button><button class="new-entry-choice" data-action="entryingredients"><strong>🥘 Aus Zutaten erstellen</strong><span>Gericht aus gespeicherten Lebensmitteln zusammenstellen</span></button></div>`)}
function recipeEditSnapshot(){const existing=find(S.recipes,recipeEditingId);return existing||null}
function recipeEditCapture(){if(recipeIsDirect(recipeEditSnapshot()))return;document.querySelectorAll('.recipe-edit-row').forEach((row,i)=>{if(recipeEditItems[i])recipeEditItems[i].amount=n(row.querySelector('input')?.value)});}
function recipeEditorSheet(){const r=recipeEditSnapshot();if(!r)return wrapSheet('Gericht bearbeiten','<p class="small muted">Gericht nicht gefunden.</p>');if(recipeIsDirect(r))return directRecipeSheet(true);return wrapSheet('Gericht bearbeiten',`<form id="recipeeditform"><div class="field"><label>Name</label><input id="editrecipename" value="${esc(r.name)}" required></div><div class="field"><label>Symbol</label><select id="editrecipeicon">${[...new Set([...FOOD_ICON_CHOICES,recipeIcon(r)])].map(i=>`<option ${i===recipeIcon(r)?'selected':''}>${i}</option>`).join('')}</select></div><div class="section-title">Zutaten und Mengen</div><div class="recipe-edit-items">${recipeEditItems.map((x,i)=>{let f=x.snapshot||find(S.foods,x.foodId);return `<div class="recipe-edit-row"><span>${esc(f?.name||'Unbekanntes Lebensmittel')}</span><input inputmode="decimal" value="${num(x.amount,2)}" aria-label="Gramm ${esc(f?.name||'Zutat')}"><span class="muted small">g</span><button type="button" class="btn sm secondary" data-action="recipeitemremove:${i}" aria-label="Zutat entfernen">×</button></div>`}).join('')}</div><div class="field"><label>Weitere Zutat hinzufügen</label><div class="searchrow"><select id="recipeaddfood"><option value="">Lebensmittel wählen …</option>${sortEntries(S.foods.filter(f=>f.kind==='food'),'alpha').map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select><button class="btn secondary" type="button" data-action="recipeitemadd">＋</button></div></div><p class="small muted">Die Nährwerte werden aus den Zutaten berechnet.</p><button class="btn full" type="submit">Gericht speichern</button></form>`)}
function saveRecipeEdit(){const r=recipeEditSnapshot();if(!r)return;recipeEditCapture();const name=$('#editrecipename')?.value.trim();if(!name||!recipeEditItems.length||recipeEditItems.some(i=>!Number.isFinite(i.amount)||i.amount<=0||i.amount>50000))return toast('Name und gültige Zutatenmengen eingeben.');const newR={...r,name,icon:$('#editrecipeicon').value,items:structuredClone(recipeEditItems),sugar:mealTotals({items:recipeEditItems}).sugar,sugarQuality:'berechnet'};S.recipes=S.recipes.map(x=>x.id===r.id?newR:x);recipeEditingId=null;sheet='managefoods';sync();toast('Gericht aktualisiert. Alte Einträge bleiben unverändert.');}
function importSheet(){return wrapSheet('Backup importieren',`<p class="small">Wähle eine zuvor exportierte JSON-Datei. Die Daten werden zunächst geprüft.</p><div class="field"><input type="file" id="backupfile" accept=".json,application/json"></div><div class="hint"><strong>Achtung:</strong> Beim Import werden alle vorhandenen Einträge, Lebensmittel, Trainings und Einstellungen vollständig ersetzt. Es findet keine Zusammenführung statt.</div><button class="btn full" style="margin-top:15px" data-action="confirmimport">Datei prüfen und importieren</button>`)}
function clearSheet(){return wrapSheet('Alle Daten löschen',`<p>Dieser Schritt löscht unwiderruflich alle lokal gespeicherten Daten.</p><div class="field"><label>Zum Bestätigen LÖSCHEN eingeben</label><input id="cleartext" autocomplete="off" placeholder="LÖSCHEN"></div><button class="btn full" data-action="confirmclear">Alle Daten endgültig löschen</button>`)}
function renderSheet(){return ({managefoods:manageFoodsSheet,newentry:newEntrySheet,recipeeditor:recipeEditorSheet,meal:mealSheet,quantity:quantitySheet,mealreview:mealReviewSheet,food:foodSheet,drink:drinkSheet,weight:weightSheet,measure:measureSheet,training:trainingSheet,scan:scanSheet,recipe:recipeSheet,directrecipe:directRecipeSheet,goal:goalSheet,import:importSheet,clear:clearSheet,calorie:calorieSheet}[sheet]||(()=>''))()}
function scheduleSearchReveal(){clearTimeout(searchScrollScheduled);searchScrollScheduled=setTimeout(revealSearchResults,180)}
function revealSearchResults(){let field=document.activeElement;if(!field||!['foodquery','recipequery'].includes(field.id))return;let sh=field.closest('.sheet'),results=field.id==='foodquery'?$('#foodresults'):$('#reciperesults');if(!sh||!results)return;let shTop=sh.getBoundingClientRect().top, fieldTop=field.getBoundingClientRect().top,desired=shTop+65;if(fieldTop>desired+12)sh.scrollBy({top:fieldTop-desired,behavior:'auto'});let first=results.querySelector('.foodresult')||results;let rect=first.getBoundingClientRect(),boundary=sh.getBoundingClientRect().bottom-15;if(rect.bottom>boundary&&rect.height<sh.clientHeight*.7)sh.scrollBy({top:rect.bottom-boundary,behavior:'auto'});}
