function markAmountChips(inputId){const input=$('#'+inputId),row=inputId==='quantity'?$('#quantityform .chiprow'):$('#drinkform .chiprow');if(!input||!row)return;const value=n(input.value);row.querySelectorAll('[data-action]').forEach(button=>{const amount=Number(button.dataset.action.split(':')[1]),active=Math.abs(value-amount)<0.0001;button.classList.toggle('sel',active);button.setAttribute('aria-pressed',String(active))})}
function updateQuantityPreview(){markAmountChips('quantity');let el=$('#quantitypreview');if(!el||!selectedFood)return;let unitFactor=quantityMode==='portion'&&selectedFood.kind!=='drink'?(selectedFood.portions?.[quantityPortion]?.amount||1):1;let t=foodTotals(selectedFood,n($('#quantity')?.value)*unitFactor);el.textContent=`${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0)} g ${metricLabel()}`}
function updateDrinkPreview(){markAmountChips('drinkamount');let el=$('#drinkpreview');if(!el)return;let f=selectedDrink||find(S.foods,find(S.drinks,editId)?.foodId);if(!f)return;let t=foodTotals(f,n($('#drinkamount').value));el.textContent=`${num(t.kcal,0)} kcal · ${num(t[secondaryMetric()]||0)} g ${metricLabel()}`}
function exportBackup(){let blob=new Blob([JSON.stringify({app:'aufbau-pwa',version:1,exportedAt:new Date().toISOString(),data:S},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aufbau-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Backup-Datei erstellt. Bitte sicher aufbewahren.')}
async function importBackup(){let file=$('#backupfile')?.files?.[0];if(!file)return toast('Bitte eine JSON-Datei auswählen.');let incoming;try{incoming=JSON.parse(await file.text())}catch{return toast('Datei ist kein gültiges JSON.')}if(incoming.app!=='aufbau-pwa'||incoming.version!==1||!incoming.data||!STORES.every(k=>k in incoming.data)||!['settings','meta'].every(k=>typeof incoming.data[k]==='object')||!STORES.filter(k=>!['settings','meta'].includes(k)).every(k=>Array.isArray(incoming.data[k])))return toast('Backup-Format ungültig oder nicht unterstützt.');if(!confirm('ACHTUNG: Alle vorhandenen Daten werden vollständig ERSETZT. Wirklich importieren?'))return;S=incoming.data;S.meta=S.meta||{};S.meta.setupComplete=true;S.settings.sugarGoal=S.settings.sugarGoal||90;S.settings.secondaryMetric=S.settings.secondaryMetric||'protein';await persist();await seedCatalog();await migrateCatalogIcons();await migrateSugarCatalog();closeSheet();render();toast('Backup erfolgreich importiert.')}
function stopCamera(){detectorLoop++;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}}
async function startCamera(){stopCamera();let marker=detectorLoop;let container=$('#camera');if(!container)return;if(!navigator.mediaDevices?.getUserMedia){container.innerHTML='<div>Keine Kamera verfügbar.<br><span class="small">Bitte Barcode unten eingeben.</span></div>';return}try{let stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(marker!==detectorLoop||sheet!=='scan'){stream.getTracks().forEach(t=>t.stop());return}cameraStream=stream;container.innerHTML='<video autoplay muted playsinline id="livevideo"></video><div class="camerascan"></div>';let video=$('#livevideo');video.srcObject=stream;await video.play();if('BarcodeDetector'in window){let detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']});(async function detect(){if(marker!==detectorLoop||sheet!=='scan')return;try{let result=await detector.detect(video);if(result.length&&result[0].rawValue){let code=result[0].rawValue;stopCamera();await fetchProduct(code);return}}catch(e){console.debug('Scanner',e)}setTimeout(detect,300)})()}else{$('#scanstatus').textContent='Dieser Browser unterstützt die automatische Barcode-Erkennung nicht. Bitte Barcode manuell eingeben.'}}catch(e){if(container)container.innerHTML='<div>Kamera nicht verfügbar.<br><span class="small">Bitte Barcode manuell eingeben.</span></div>';console.debug(e)}}
async function lookupBarcode(){let code=$('#barcodefield').value.replace(/\s/g,'');if(!/^\d{8,14}$/.test(code))return toast('Bitte eine gültige EAN/GTIN (8–14 Ziffern) eingeben.');stopCamera();await fetchProduct(code)}
async function fetchProduct(code){let status=$('#scanstatus');if(status)status.textContent='Produkt wird gesucht …';let existing=S.foods.find(f=>f.barcode===code);if(existing){selectedFood=existing;if(currentBarcodeContext==='drink'&&existing.kind==='drink'){selectedDrink=existing;sheet='quantity'}else if(currentBarcodeContext==='food'){sheet='food';editId=existing.id;foodEditingId=existing.id}else{sheet='quantity'}render();toast('Produkt aus lokaler Datenbank gefunden.');return}try{let response=await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=code,product_name,product_name_de,nutriments`,{headers:{Accept:'application/json'}});if(!response.ok)throw Error(`HTTP ${response.status}`);let json=await response.json(),product=json.product;if(json.status!==1||!product){if(status)status.textContent='Produkt nicht gefunden. Du kannst es manuell anlegen.';return toast('Produkt nicht gefunden. Bitte manuell anlegen.')}let name=(product.product_name_de||product.product_name||'').trim();let nut=product.nutriments||{};let kcal=Number(nut['energy-kcal_100g']),protein=Number(nut['proteins_100g']);if(!Number.isFinite(kcal))kcal=null;if(!Number.isFinite(protein))protein=null;let context=currentBarcodeContext;sheet='food';editId=null;render();$('#foodname').value=name;$('#foodname').dataset.barcode=code;const barcodeField=$('#foodbarcode');if(barcodeField)barcodeField.value=code;$('#foodkcal').value=kcal??'';$('#foodprotein').value=protein??'';const sugarValue=Number(nut['sugars_100g']);if(Number.isFinite(sugarValue)&&nut['sugars_100g']!=null)$('#foodsugar').value=sugarValue;if(context==='drink'){let b=document.querySelector('[data-action="foodkind:drink"]');b?.click()}let msg=$('#scannedmsg');msg.style.display='block';msg.textContent='Produktdaten von Open Food Facts übernommen. Bitte Name und Nährwerte prüfen und gegebenenfalls korrigieren. Fehlende Werte bleiben leer.';toast('Produkt gefunden – bitte Angaben kontrollieren.')}catch(e){console.warn('Open Food Facts',e);if(status)status.textContent='Online-Abfrage fehlgeschlagen. Internetverbindung prüfen oder Lebensmittel manuell anlegen.';toast('Online-Abfrage fehlgeschlagen. Manuelle Eingabe möglich.')}}
function main(){try{const d=JSON.parse(localStorage.getItem('weight-app-setup-draft-v1')||'null');if(d?.data){onboardingDraft={...onboardingDraft,...d.data};onboardingStep=Math.max(0,Math.min(2,Number(d.step)||0))}}catch(e){}restoreTraining();trainingTicker=setInterval(updateTrainingClocks,250);openDB().then(async d=>{db=d;await load();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn)}).catch(e=>{$('#app').innerHTML='<div class="loading">Die lokale Datenbank konnte nicht geöffnet werden. Bitte überprüfe, ob private Speicherung im Browser aktiviert ist.<p>'+esc(e.message)+'</p></div>'})}main();
